/* 圖鑑說明（自動產生，來源 PokeAPI；腳本見專案文件「寶可夢資料腳本」）DEX_TEXT[DEX索引] = [分類, 官方說明, 身高(0.1m), (1＝由官方簡體說明轉換)]；第一次開圖鑑詳細頁才載入 */
var DEX_TEXT = [["種子寶可夢", "在出生後的一段時間內，牠會吸收背上種子裡儲存著的營養成長。", 7], ["種子寶可夢", "沐浴在陽光下越久，身體內會湧出越多力量，背上的花苞也會漸漸成長。", 10], ["種子寶可夢", "花朵散發出的迷人香味，能安撫激動的心情，甚至消弭鬥爭。", 20], ["蜥蜴寶可夢", "從出生時開始尾巴上就有火焰在燃燒。火焰熄滅時，生命也會結束。", 6], ["火焰寶可夢", "如果牠在戰鬥中亢奮起來，就會噴出灼熱的火焰，把周圍的東西燒得一乾二淨。", 11], ["火焰寶可夢", "能用翅膀飛到距離地面１４００公尺的高度。會吐出高溫的火焰。", 17], ["小龜寶可夢", "當牠遇到危險的時候，會將四肢收回甲殼裡保護自己，同時從嘴裡噴出水來。", 5], ["龜寶可夢", "會靈巧地擺動自己毛茸茸的耳朵和尾巴，藉此在水中保持平衡。", 10], ["甲殼寶可夢", "從甲殼上的大炮裡放出的噴射水流足以貫穿厚實的鐵板。", 16], ["蟲寶寶寶可夢", "別看牠的腳很短，因為是吸盤，所以無論是斜坡還是牆壁都能輕鬆前進。", 3], ["蛹寶可夢", "雖然有堅硬的外殼，但因為殼裡的身體很軟，所以無法抵抗強力的攻擊。", 7], ["蝴蝶寶可夢", "每天都忙著採集花蜜。習慣在腿部的細毛上塗滿花蜜，然後帶回巢穴裡。", 11], ["毛毛蟲寶可夢", "頭上長著尖銳的針。總是躲在森林或是草叢裡，不停地吃著葉子。", 3], ["蛹寶可夢", "雖然幾乎動也動不了，但如果遭遇到了危險，有時似乎會豎起毒刺來反抗。", 6], ["毒蜂寶可夢", "會用雙手和屁股上的３根毒針不斷猛刺來攻擊對手。", 10], ["小鳥寶可夢", "性情溫馴，即使遭到襲擊也很少反擊，只會朝對手潑沙子來保護自己。", 3], ["鳥寶可夢", "擁有著超乎尋常的體力，會在廣大的地盤裡四處飛行，到遠處去尋找食物。", 11], ["鳥寶可夢", "會以２馬赫的速度飛行來尋找食物。巨大的爪子是很可怕的武器。", 15], ["鼠寶可夢", "長著２顆大牙，碰到什麼都會先咬上一口。只要看見１隻出沒，附近肯定還住著40隻以上。", 3], ["鼠寶可夢", "為了取得水中的食物，牠會利用後腳上的小蹼在河裡游泳。", 7], ["小鳥寶可夢", "不擅長高空飛行。會以超高速在地盤裡四處盤旋，確保自己的地盤不被侵犯。", 3], ["鳥嘴寶可夢", "從很久以前就已存在的寶可夢。只要察覺到絲毫的危險，就會立刻飛上高空躲避。", 12], ["蛇寶可夢", "身體會隨著年齡增長不斷變長。每到夜裡就會把身體纏繞在樹枝上歇息。", 20], ["眼鏡蛇寶可夢", "根據目前已知的研究結果，長在牠肚子上的可怕花紋一共有６種不同的類型。", 35], ["鼠寶可夢", "皮卡丘們把尾巴貼在一起交換電流，其實是在互相打招呼。", 4], ["鼠寶可夢", "如果電囊空了，牠就會直直地豎起尾巴，收集空氣中的電流。", 8], ["鼠寶可夢", "會在地面挖洞築巢。即使遇到地下堅硬的岩石，也會用銳利的爪子擊碎並向前挖進。", 6], ["鼠寶可夢", "會用銳利的爪子當作鉤子來爬樹。這是為了將樹果擊落，分給在樹下等待的穿山鼠們。", 10], ["毒針寶可夢", "會用堅硬的門牙咬碎樹果後吃下。角的尖端會比雄性還要圓一些。", 4], ["毒針寶可夢", "有危險逼近群體時，會與夥伴們團結一致地用超音波的大合唱來攻擊。", 8], ["鑽錐寶可夢", "會把孩子放在背上的刺與刺之間來哄牠們。這時候絕對不會釋放毒素。", 13], ["毒針寶可夢", "體型嬌小，但性情勇猛。為了保護感情好的雌性，會奮不顧身地勇敢戰鬥。", 5], ["毒針寶可夢", "神經質且容易發脾氣打架。當體內的腎上腺素增加時，毒素的濃度也會提升。", 9], ["鑽錐寶可夢", "以力氣為傲的寶可夢。會善用粗壯的尾巴和連鑽石也能擊碎的角，豪邁地戰鬥。", 14], ["妖精寶可夢", "因可愛的舉止和叫聲而廣受歡迎的寶可夢。不過很少被人發現。", 6], ["妖精寶可夢", "聽覺靈敏，連１公里以外針落地的聲音都聽得見，因此平時會待在安靜的地方。", 13], ["狐狸寶可夢", "隨著身體的成長，６根尾巴的毛髮也會變得更漂亮。緊緊抱著牠時能感到微微的溫暖。", 6], ["狐狸寶可夢", "聰明伶俐但很會記仇。據說如果敢亂抓牠的尾巴，牠就會纏著你作祟１０００年。", 11], ["氣球寶可夢", "會自在地改變聲音的波長，唱出一聽見就絕對會昏昏欲睡的神奇旋律。", 5], ["氣球寶可夢", "以自己細緻的體毛為傲。尤其額頭上的捲毛，更是有著彷彿會一摸升天的極致觸感。", 10], ["蝙蝠寶可夢", "棲息在陽光照射不到的洞窟裡。到了早上就會和夥伴相聚，一邊互相取暖一邊睡覺。", 8], ["蝙蝠寶可夢", "能以小小的腳靈巧地步行。會無聲無息地靠近沉睡中的獵物，用獠牙咬住對方並且吸食血液。", 16], ["雜草寶可夢", "白天為了躲避太陽，會鑽進涼爽的地下。藉由沐浴月光來成長。", 5], ["雜草寶可夢", "看似口水的東西其實是甜甜的蜜。非常黏稠，只要碰到就會一直黏住。", 8], ["花寶可夢", "雖然花瓣越大就能放出越多的花粉，但頭部也會隨之變重而容易疲倦。", 12], ["蘑菇寶可夢", "會挖掘洞穴，從樹木的根部獲取營養，但幾乎所有的營養都會被背上的蘑菇奪走。", 3], ["蘑菇寶可夢", "由於蟲子的精華不斷被吸走，在思考的似乎已經不是蟲子，而是背上的蘑菇了。", 10], ["昆蟲寶可夢", "在明亮的地方看就會發現那對有著雷達作用的大眼睛，是由許多小眼睛聚集而成的。", 10], ["毒蛾寶可夢", "翅膀上的鱗粉一旦沾到身上就很難甩掉，而且鱗粉帶有的毒素還會逐漸滲入體內。", 15], ["鼴鼠寶可夢", "在地下較淺的地方移動。被牠挖掘過的地面會鼓起來，所以非常容易發現。", 2], ["鼴鼠寶可夢", "三胞胎的地鼠，擁有能夠挖掘到地下１００公里深的潛力。沒人知道牠在地下的部分究竟長成什麼樣子。", 7], ["妖怪貓寶可夢", "為了不弄髒額頭上的金幣，會常常洗臉。和伽勒爾的喵喵關係不好。", 4], ["暹羅貓寶可夢", "擁有優雅高貴的身姿。與野蠻的喵頭目個性不合，互相看不起對方。", 10], ["鴨寶可夢", "頭痛會隨著壓力累積而更加劇烈。會用強大的念力壓倒周圍的一切。", 8], ["鴨寶可夢", "民間故事裡相傳，牠會把弄髒河川的人類拖進水裡帶走。", 17], ["豬猴寶可夢", "體態輕盈的牠居住在樹上。常因為一些小事而生氣，往身邊的東西飛撲過去。", 5], ["豬猴寶可夢", "只有當誰都不在身邊的時候才會停止生氣。然而要看到牠不生氣的樣子是很困難的。", 10], ["小狗寶可夢", "性格忠誠。為了保護自己的訓練家，會拼命地朝對手狂吠。", 7], ["傳說寶可夢", "從古時候起就是擄獲眾多人心的美麗寶可夢。能像飛一樣輕盈地奔跑。", 19], ["蝌蚪寶可夢", "在水流湍急的河川裡，會把厚厚的嘴唇當作吸盤，吸附在岩石上避免被沖走。", 6], ["蝌蚪寶可夢", "流的汗是又黏又滑的黏液狀。即使被敵人捉住，也能滑溜溜地輕易逃脫。", 10], ["蝌蚪寶可夢", "除了游泳之外，也擅長使用格鬥技。完美鍛鍊的手臂可以使出豪邁的拳擊。", 13], ["念力寶可夢", "就算在睡夢中也能使用瞬間移動。據說當牠睡得越熟，瞬間移動的距離就會越遠。", 9], ["念力寶可夢", "念力的威力大得驚人。會把精神力量儲存在額頭的星星裡，以備進化所需。", 13], ["念力寶可夢", "能操控強大的超能力。雙手中的湯匙據說就是用牠的力量創造出來的。", 15], ["怪力寶可夢", "時時刻刻都充滿力量。由於體力過剩而去舉岩石消磨時間，也因此變得更強。", 8], ["怪力寶可夢", "有著不會疲勞的強韌肉體。會去幫助人類完成例如搬運沉重行李之類的工作。", 15], ["怪力寶可夢", "４隻手臂在思考之前就會反射性地行動，使出多發拳擊。", 16], ["花寶可夢", "喜歡高溫多濕的環境。會利用藤蔓捕捉小蟲當成自己的食物。", 7], ["捕蠅寶可夢", "肚子餓的時候會把周圍會動的東西全都吞下去，然後用溶解液致其於死地。", 10], ["捕蠅寶可夢", "會用花蜜的香氣引誘獵物。據說被牠吞進了嘴裡的東西只要１天就會溶解到連骨頭都不剩。", 17], ["水母寶可夢", "絕大部分都是由水組成的身體在海中會與海水同化，令其他生物很難看見牠。", 9], ["水母寶可夢", "能夠自由伸縮身上的８０根觸手。會像撒網般張開觸手捕捉獵物，並用毒針注入劇毒。", 16], ["岩石寶可夢", "大量棲息在山路之類的地方。不小心踩到牠會讓牠生氣，所以走路的時候要小心。", 4], ["岩石寶可夢", "經常在山路上滾動。滾動時從不會去理會前面的路上有什麼東西。", 10], ["重量級寶可夢", "剛蛻皮的時候身體比較軟而且顏色偏白，但在接觸到空氣後很快就會變硬。", 14], ["火馬寶可夢", "得到了小火馬認可的人，在觸摸牠燃燒著的鬃毛時不會覺得燙手，真是不可思議。", 10], ["火馬寶可夢", "奔跑速度最快的烈焰馬會成為首領，決定族群前往的地點和奔跑速度。", 17], ["憨憨寶可夢", "尾巴浸在水裡時會滲出甜味，牠會以此當誘餌來吸引並且釣起寶可夢。", 12], ["寄居蟹寶可夢", "被大舌貝狠狠咬下的衝擊讓牠變得能用兩腳行走。如果大舌貝脫落了，牠似乎就會變回呆呆獸。", 16], ["磁鐵寶可夢", "靠吞食電力維持生命。會一邊從左右的組件放射出電磁波，一邊在空中飛。", 3], ["磁鐵寶可夢", "隨時都釋放著很強的磁力。只要三合一磁怪一靠近，大多數的電腦都會出現異常。", 10], ["黃嘴鴨寶可夢", "用植物的莖來戰鬥。莖的揮舞方式存在著好幾種不同的流派。", 8], ["兩頭鳥寶可夢", "翅膀短小不擅長飛行，但是擁有發達的雙腳，能以很快的速度奔跑。", 14], ["三頭鳥寶可夢", "嘟嘟的其中一個頭分裂形成的變種。能以60公里的時速在草原上奔馳。", 18], ["海獅寶可夢", "喜歡滴水成冰的寒冷地方。在零下10度的溫度裡也能舒服自在地游泳。", 11], ["海獅寶可夢", "全身上下一片雪白。不畏寒冷，在滿是浮冰的海上也能元氣十足地游來游去。", 17], ["污泥寶可夢", "由許多污泥凝聚而成。散發著惡臭，讓人無法觸碰。經過的地方寸草不生。", 9], ["污泥寶可夢", "奇臭無比！雖然臭到令人昏倒，但臭臭泥的鼻子已經退化，所以牠自己聞不到味道。", 12], ["雙殼貝寶可夢", "堅硬的殼能反彈任何攻擊。如果在殼張開時被攻擊到內部，就會變得十分脆弱。", 3], ["雙殼貝寶可夢", "一旦牠把殼閉上，無論是擁有什麼樣怪力的人都無法將其打開。", 15], ["氣體狀寶可夢", "能用稀薄氣體狀的身體潛入任何地方，但只要起風就會被吹跑。", 13], ["氣體狀寶可夢", "如果黑暗中空無一人，但你卻感覺被什麼盯上了，那麼鬼斯通一定就在那裡。", 16], ["影子寶可夢", "據說牠會為了奪取山中遇難者的生命而從黑暗中出現。", 15], ["岩蛇寶可夢", "彎曲扭動巨大結實的身體，以時速８０公里的猛烈勢頭挖掘前進。", 88], ["催眠寶可夢", "如果每晚和牠一起睡覺，有時會讓你夢見牠過去吃過的夢。", 10], ["催眠寶可夢", "要是不小心遇上牠，要趕緊從牠身上移開視線，否則會有被牠手上擺錘催眠的危險。", 16], ["清水蟹寶可夢", "如果危險逼近，就會從嘴裡吐出泡沫包裹全身，讓身體看起來更大。", 4], ["鉗子寶可夢", "巨大的鉗子破壞力十足，但是因為太過沉重，不戰鬥的時候就很礙事。", 13], ["球寶可夢", "據說和精靈球相似的外型是牠的保護色，但令人意外地牠其實很容易就會自爆。", 5], ["球寶可夢", "只要受到任何一點衝擊，體內的電能就會迅速膨脹然後爆炸。", 12], ["蛋寶可夢", "非得湊齊６隻才會有安全感。那怕只是少了１隻，都會立刻變得很膽小，隨時想要逃跑。", 4], ["椰子寶可夢", "３顆頭團結一致發出的精神力量威力強大。天氣變陰時動作就會變得遲緩。", 20], ["孤獨寶可夢", "頭上戴著死去母親的頭骨。雖然有時會因為作夢而哭泣，但每次流淚後都會變得更強。", 4], ["愛骨寶可夢", "進化時，原本戴在頭上的母親頭骨化為了牠身體的一部份。不但如此，性格也變得很凶暴。", 10], ["踢腿寶可夢", "雙腿能夠自由伸縮，即使離得很遠也能把對手一腳踢飛。", 15], ["拳擊寶可夢", "打出的拳擊甚至能劈開空氣。但連續攻擊３分鐘後，牠似乎就會想休息一下。", 14], ["舔舔寶可夢", "蟲寶可夢是牠主要的食物。會用長長的舌頭去把對方舔麻痺，然後趁機一口吞下。", 12], ["毒氣寶可夢", "污濁的空氣是牠的美味大餐。據說在昔日的伽勒爾地區曾經存在著更多的瓦斯彈。", 6], ["毒氣寶可夢", "雖然吸入空氣的力量稍弱於伽勒爾的雙彈瓦斯，製造出的毒素卻更加強力。", 12], ["尖尖寶可夢", "腦子裡只能記住一件事。一旦開始猛衝，不管理由是什麼都會很快感到無所謂而忘掉。", 10], ["鑽錐寶可夢", "全身被鎧甲般的皮膚保護著。甚至能在２０００度的熔岩中生存。", 19], ["蛋寶可夢", "原本動作遲緩。但為了從盯上蛋的傢伙們手裡保護蛋，逃跑的速度就變快了。", 11], ["藤蔓狀寶可夢", "藤蔓散發著獨特的香氣。在伽勒爾的部分地區會被當作香草使用。", 10], ["親子寶可夢", "紀錄中記載著，曾經有沒孩子的袋獸養育了遇難的人類孩子。", 22], ["龍寶可夢", "會在水中跳舞似地游動來製造漩渦。玩耍時會和夥伴比賽誰做出的漩渦比較大。", 4], ["龍寶可夢", "嘴部雖然細，但吸力卻很強。就算是比嘴還要大的食物，也都能瞬間吸進口裡吃掉。", 12], ["金魚寶可夢", "背鰭和尾鰭像肌肉那樣發達。能夠以５節的速度在水中游泳。", 6], ["金魚寶可夢", "金魚王之所以會用角挖穿河底的岩石來築巢，是為了防止產下的卵被水流沖走。", 13], ["星形寶可夢", "會被魚寶可夢啄食，但是即使身體被咬斷也能很快就再生，所以一點都不在意。", 8], ["謎寶可夢", "會高速旋轉著身體在海裡游泳，並且同時吸食微小的浮游生物。", 11], ["屏障寶可夢", "擅長表演默劇。用手指放出的波動製造牆壁，保護自己免於大多數的攻擊。", 13], ["螳螂寶可夢", "如果在森林裡發現了有很多樹被砍倒的地方，那就是飛天螳螂的地盤。", 15], ["人形寶可夢", "許多伽勒爾的迷唇姐擁有美麗又纖細的聲音，甚至有一批對牠們著迷的粉絲。", 14], ["電擊寶可夢", "暴風雨來臨時，牠們會聚集在高大的樹周圍，靜靜地一直等待落雷。", 11], ["吐火寶可夢", "全身時時刻刻都在燃燒。人們認為牠是引起火災的原因之一，非常畏懼牠。", 13], ["鍬形蟲寶可夢", "會用角緊緊夾住獵物，就這樣把對方剪成兩半或是把牠硬扔到天邊去。", 15], ["暴牛寶可夢", "棲息在伽勒爾的肯泰羅性格暴躁，絕不會允許人類騎到自己的背上。", 14], ["魚寶可夢", "又弱又可憐的寶可夢。在水流比較快的地方，只能任憑自己被水沖走。", 9], ["凶惡寶可夢", "就算是在狂風暴雨中，只要發狂的暴鯉龍出現，一切都會被牠燒毀殆盡。", 65], ["乘載寶可夢", "十分耐寒，不畏冰海。皮膚滑滑的，摸起來會有點涼。", 25], ["變身寶可夢", "當兩隻百變怪相遇的時候，為了能變成和對方相同的樣子，牠們動起來會比平常更加劇烈。", 3], ["進化寶可夢", "由於不穩定的基因，蘊含著各式各樣進化可能性的特殊寶可夢。", 3], ["吐泡寶可夢", "身體細胞的結構與水分子相似。牠能和水融為一體，讓別人無法看見牠。", 10], ["雷寶可夢", "有時會吸入空氣中的負離子，吐出大約１００００伏特的高壓電。", 8], ["火寶可夢", "會將吸入的空氣的一部分傳送到自己體內的火囊裡，製造出１７００度的火焰。", 9], ["虛擬寶可夢", "近年在電腦空間大展身手。會四處巡邏查看有沒有可疑的資料。", 8], ["漩渦寶可夢", "一度滅絕的古代寶可夢。會使用１０隻腳划水，在水中一漂一浮地游動。", 4], ["漩渦寶可夢", "尖銳的牙齒足以咬碎岩石，但能夠襲擊的獵物僅限在牠的觸手可及的範圍之內。", 10], ["甲殼寶可夢", "雖然有人說這種寶可夢已經滅絕，但牠在一部分地區似乎是相當常見的。", 5], ["甲殼寶可夢", "沒有人知道牠為何會滅絕。過去曾棲息在溫暖的海域，是性情凶暴的古代寶可夢。", 13], ["化石寶可夢", "擁有像鋸子般的牙齒，就連鋼屬性寶可夢的皮膚都能撕裂成碎片。", 18], ["瞌睡寶可夢", "擁有一個結實的胃，即使吃了發霉腐爛的東西，也完全不會吃壞肚子。", 21], ["冰凍寶可夢", "擁有能自在操縱冰的能力。據說是棲息在永凍之地的雪山中。", 17], ["電擊寶可夢", "傳說的鳥寶可夢。據說只要牠磨蹭翅膀，立刻就會有雷電劈下。", 16], ["火焰寶可夢", "相傳牠會以美麗燃燒的翅膀照亮山路，救助在山中遇險的人。", 20], ["龍寶可夢", "長久以來被認為只存在於幻想之中。額頭上小小的突起是正在成長的角。", 18], ["龍寶可夢", "能將力量集中在尾巴的珠子，藉此操縱天氣。全身散發著氣場的樣子非常神秘。", 40], ["龍寶可夢", "人們稱牠為大海的化身。有許多船會在船頭設置快龍的雕像。", 22], ["基因寶可夢", "身上的基因與夢幻幾乎一樣，但無論是體型大小還是性格都與夢幻有著巨大的差別。", 20], ["新種寶可夢", "用顯微鏡觀察就會發現，牠的身上長著又細又短，十分細緻的體毛。", 4], ["葉子寶可夢", "非常喜歡沐浴陽光。會用頭上的葉子來尋找溫暖的地方。", 9, 1], ["葉子寶可夢", "只要聞到從它脖子周圍散發出的像香辛料一樣的香味，不知為何就會想要對戰。", 12, 1], ["芳草寶可夢", "只要待在大竺葵身邊，就會像享受了森林浴一樣，讓心情變得清新舒暢。", 18, 1], ["火鼠寶可夢", "平時會將背部蜷起。但當它發怒或受驚時，會從背部噴出火焰。", 5, 1], ["火山寶可夢", "戰鬥前會背過身去向對手展示自己的火焰有多麼厲害。", 9, 1], ["火山寶可夢", "該寶可夢藏有大絕招。會摩擦熊熊燃燒著的體毛，掀起爆炸氣浪進行攻擊。", 17, 1], ["大顎寶可夢", "因為它發達的顎充滿了力量，不管是什麼都能咬碎，所以就算是它的訓練家也要當心。", 6, 1], ["大顎寶可夢", "向後彎曲的牙齒尖端讓它一旦叼住獵物，就絕不會鬆口。", 11, 1], ["大顎寶可夢", "會用大而有力的顎咬住對手，然後就那樣甩動脖子將對手撕得粉碎。", 23, 1], ["放哨寶可夢", "警戒心很強的寶可夢。柔韌擺動的尾巴肌肉發達，摸上去很硬。", 8, 1], ["長軀幹寶可夢", "在細長的巢穴中養育孩子。等孩子長大後，就會讓孩子到巢穴外做獨立生活的準備。", 18, 1], ["貓頭鷹寶可夢", "總是在固定的時間鳴叫，因此也有訓練家拿牠來代替鐘錶帶出門。", 7], ["貓頭鷹寶可夢", "開始思考事情時，會將脖子旋轉１８０度，提高大腦的工作效率。", 16], ["五星寶可夢", "非常膽小的寶可夢。會和夥伴一起張開反射壁，藉此保護巢穴。", 10], ["五星寶可夢", "一邊撒落閃閃發亮的粉末，一邊在夜空中飛翔。據說如果身上沾到這種粉末，就會有好事發生。", 14], ["吐絲寶可夢", "牙齒的毒性並不強烈，但用來削弱那些掛在蛛網上無法動彈的獵物是綽綽有餘。", 5], ["長腿寶可夢", "會吐絲來捕捉獵物。每到夜晚就會離開巢穴，積極地展開狩獵。", 11], ["蝙蝠寶可夢", "能夠自在地控制４隻翅膀振翅飛翔。即使是在狹窄的洞窟裡也能毫不減速地飛舞。", 18], ["琵琶魚寶可夢", "在黑暗的海底，觸手上不斷閃爍的亮光是牠唯一的通訊手段。", 5], ["燈寶可夢", "發出強光讓獵物暫時失明。趁獵物露出破綻時，用電擊招呼對手。", 12], ["小鼠寶可夢", "臉頰上的電囊還很小，如果囊裡的電太多了，就會漏出來電到自己。", 3], ["星形寶可夢", "有著如同星星一般的輪廓。因為這樣的外型，人們相信牠是乘著流星而來的。", 3], ["氣球寶可夢", "會用柔軟的身體一彈一跳地四處移動。體溫上升時，身體就會變成深粉紅色。", 3], ["針球寶可夢", "好運的象徵。據說在牠的殼裡裝著滿滿的幸福。", 3], ["幸福寶可夢", "不待在溫柔的人身邊就會變得沒有精神。不揮動翅膀也能浮在空中。", 6], ["小鳥寶可夢", "翅膀還沒有完全長好，所以只能一跳一跳地移動。一直在注視著什麼。", 2], ["神秘寶可夢", "能夠看穿過去和未來。日復一日注視著太陽動向的奇異寶可夢。", 15], ["綿毛寶可夢", "會累積絨毛摩擦時所產生的電力。如果因為牠可愛而直接用手去摸，就會被電得又麻又痛。", 6], ["綿毛寶可夢", "會將電力儲存在鬆軟的毛中。因為儲存了太多電力，身上有些地方變得光禿禿的。", 8], ["燈寶可夢", "尾巴發出的耀眼光芒被船員們當成引路的路標，從過去就一直深受重視。", 14], ["花寶可夢", "有時美麗花們會聚在一起，做出像是跳舞的動作。據說這是呼喚太陽的儀式。", 4], ["水鼠寶可夢", "很能彈開水的體毛就算是從寒冷的海裡上岸時也能立刻乾掉，一點都不冷。", 4], ["水兔寶可夢", "會製作填滿空氣的泡泡。當露力麗到河裡玩耍的時候，牠就會用泡泡把露力麗包起來。", 8], ["模仿寶可夢", "為了不被襲擊而模仿樹的樣子。很討厭水，所以一開始下雨就會在不知不覺間消失無蹤。", 12], ["蛙寶可夢", "雄性的叫聲比雌性更巨大。叫聲低沉有魄力的蚊香蛙皇更能受到雌性喜愛。", 11], ["棉草寶可夢", "會隨著風移動到很遠的地方。沒有人知道帕底亞的毽子草具體是從哪裡來的。", 4, 1], ["棉草寶可夢", "據說熱愛毽子花的人能夠通過它頭上花朵散發的香味猜出它在哪裡出生的。", 6, 1], ["棉草寶可夢", "會隨季風到處旅行。當毽子棉的棉孢子掉光的時候，就是它的旅行和生命終結之時。", 8, 1], ["長尾寶可夢", "會從樹上尋找獵物。只要發現自己愛吃的甜竹竹，就會興奮地飛撲過去。", 8], ["種子寶可夢", "會在某日清晨突然掉下來。對自己的弱小心知肚明，所以直到進化為止會不斷積存養分。", 3, 1], ["太陽寶可夢", "白天總是精力充沛，隨心所欲地到處活動，但太陽下山後卻一動不動。", 8, 1], ["薄翼寶可夢", "會高速扇動翅膀讓自身停留在空中以監視自己的地盤。", 12, 1], ["水魚寶可夢", "為了在地面上行走時不讓皮膚乾燥，會用有毒的黏膜覆蓋身體。", 4], ["水魚寶可夢", "身體總是滑溜溜的。雖然游泳時頭總會撞到河底，但牠自己毫不在意。", 14], ["太陽寶可夢", "從額頭的珠子放射出精神力量進行戰鬥。當力量用盡時，珠子的顏色也會褪去。", 9], ["月光寶可夢", "在滿月之夜或是興奮的時候，牠身上圈圈一樣的花紋就會發出金黃色的光。", 10], ["黑暗寶可夢", "會為了老大尋找閃閃發亮的東西。被人們視為不吉利的象徵，厭惡牠的人也很多。", 5], ["王者寶可夢", "只要開口提問，任何難題牠都會幫忙解開，但是無人能夠理解呆呆王的語言。", 20], ["夜啼寶可夢", "會藉由模仿人哭叫的聲音嚇唬大家來取樂。不擅長應付膽大的對手。", 7], ["象徵寶可夢", "很像古代文明的文字。是先有文字還是先有未知圖騰，這是世界七大不可思議之一。", 5, 1], ["忍耐寶可夢", "為了隱藏漆黑的尾巴而悄悄地生活在黑暗之中。不會主動發動攻擊。", 13], ["長頸寶可夢", "尾巴上的腦袋雖然很小，但卻是可以發揮出強大超能力的重要器官。", 15, 1], ["蓑衣蟲寶可夢", "會用唾液把樹皮貼在自己身上，讓自己變得更厚更大。上了年紀的榛果球是無比巨大的。", 6], ["蓑衣蟲寶可夢", "只有在吞下獵物的瞬間，殼裡的身體才會出現。至今還沒有人見過牠的真面目。", 12], ["地蛇寶可夢", "居住在像是迷宮的巢穴裡。能憑土壤的氣味知道自己的位置，所以絕對不會迷路。", 15], ["飛蠍寶可夢", "在陡峭的巖壁上築巢。每次滑翔之後，就要跳著回到巢裡。", 11, 1], ["鐵蛇寶可夢", "人們認為牠的身體是因為堆積了和泥土一起吞下的鐵質，才會發生變化的。", 92], ["妖精寶可夢", "個性與外表相反，其實很膽小。要是把牠和其他小狗寶可夢放在一起，牠有可能會被欺負。", 6], ["妖精寶可夢", "雖然很受年輕女性歡迎，但牠不但膽小而且個性纖細，以看門狗來說一點用都沒有。", 14], ["氣球寶可夢", "全身上下的小針是由鱗片變化而來的。如果被刺中的話，就會中毒並陷入昏迷。", 5], ["鉗子寶可夢", "體型雖然纖細，攻擊力卻非常駭人。連身體的肌肉都是由金屬構成的。", 18], ["發酵寶可夢", "儲存在壺形甲殼裡的樹果會在不知不覺間變成黏糊糊的果汁。", 6], ["獨角寶可夢", "能夠輕輕鬆鬆舉起比自己體重還要重１００倍的物體，是以一身怪力為傲的寶可夢。", 15], ["鉤爪寶可夢", "性格狡猾且凶猛。會趁著雙親不在時侵入巢穴把蛋盜走。", 9], ["小熊寶可夢", "會偷偷跟蹤三蜜蜂找出它們的巢，然後用手掌挖起大量蜜汁來享用。", 6, 1], ["冬眠寶可夢", "雖然看上去無所畏懼，但在舔食到最喜歡的蜜時，會高興得笑逐顏開。", 18, 1], ["熔岩寶可夢", "由熔岩構成的身體有時會因變冷而缺損，但只要泡到熔岩中就能恢復。", 7, 1], ["熔岩寶可夢", "生活在火山口附近。由熔岩冷卻凝固而成的殼裡積蓄著火之能量。", 8, 1], ["小豬寶可夢", "一聞到誘人的香味時，就會不顧一切地朝香味傳來的方向飛奔而去。", 4], ["野豬寶可夢", "雖然４隻腳很短，但因為蹄很寬而且粗糙，所以就算在雪地上行走也不會打滑。", 11], ["珊瑚寶可夢", "在溫暖的大海裡生活。也曾經大量棲息於上古時期的伽勒爾近海。", 6], ["噴射寶可夢", "會用變成吸盤狀的背鰭吸附在巨翅飛魚身上，吃牠平常吃剩下的東西。", 6], ["噴射寶可夢", "有著堅硬結實的腦袋。會用帶有吸盤的腳纏住對手，然後不停地用頭猛撞。", 9], ["搬運寶可夢", "因為有跟人類及寶可夢分享自己食物的習性，所以一直都在到處尋找食物。", 9], ["風箏寶可夢", "悠然地暢游在大海中。就算有覬覦食物殘渣的鐵炮魚吸附在自己身上也毫不在意。", 21], ["鋼甲鳥寶可夢", "由於牠脫落下來的羽毛能夠製成劍，因此作為家徽的圖案也很有人氣。", 17], ["陰暗寶可夢", "會在天亮前反覆發出令人不寒而慄的長嚎，藉此強調自己群體的存在。", 6], ["陰暗寶可夢", "特徵是令人不寒而慄的長嚎。過去人們認為牠是來自地獄的使者，對牠十分畏懼。", 14], ["龍寶可夢", "脫落的鱗片光澤高雅有深度，甚至被拿去獻給王族作為貢品。", 18], ["長鼻寶可夢", "會在河邊做出巢穴棲息。玩泥巴之後如果不把身體洗乾淨，就會感到不自在。", 5, 1], ["鎧甲寶可夢", "全身包覆著堅硬的皮膚，就算被車撞到也安然無恙。但是對雨卻毫無招架之力。", 11, 1], ["虛擬寶可夢", "搭載了ＡＩ功能後，開始說起了只有多邊獸Ⅱ彼此之間才能了解的神秘語言。", 6], ["大角寶可夢", "過去生活在嚴苛的環境下，因此當時的精神力量似乎比現在還要強。", 14, 1], ["畫畫寶可夢", "會用尾巴前端分泌出的液體畫下標記。其中有些標記會吸引愛好者以高價買賣。", 12], ["打鬥寶可夢", "體型雖小卻不可輕視，因為牠只要發現合適的對手，就會馬上撲上去大打出手。", 7], ["倒立寶可夢", "會透過倒立來擾亂對方的節奏，然後趁隙施展華麗的踢擊。", 14], ["親吻寶可夢", "好奇心旺盛的寶可夢。對於任何東西都會先用嘴唇去觸碰，再決定是喜歡還是討厭這東西。", 4], ["電氣寶可夢", "還不擅長儲存電力。為了吸食電力，會偷偷潛入民宅尋找插座。", 6], ["火種寶可夢", "棲息在火山的周圍。在一天結束時，會泡進熔岩中讓身體舒緩疲勞。", 7], ["乳牛寶可夢", "如果沒有每天擠鮮奶，身體的狀況就會變糟。鮮奶的風味會隨季節改變。", 12], ["幸福寶可夢", "會生下飽含幸福的神奇的蛋。據說吃下蛋的人，就能夠對任何人都很溫和相待。", 15], ["天雷寶可夢", "據說是和雷電一同降臨的寶可夢。能夠從背上的雨雲放射出雷電。", 19, 1], ["火山寶可夢", "據說如果炎帝吼叫的話，世界上的某處火山就會噴發。", 21, 1], ["極光寶可夢", "在全世界四處奔跑，讓汙水重回清澈。會隨北風奔跑著離去。", 20, 1], ["岩石膚寶可夢", "靠吃泥土維生。吃掉一座大山後，就會為了成長而開始沉睡。", 6], ["子彈寶可夢", "雖然是蛹卻不會呆著不動。在堅硬的甲殼之下已經長出了手腳。", 12], ["鎧甲寶可夢", "當牠帶著巨大轟鳴聲邁開腳步，就連大山都會為之崩裂，周遭的地形也會因而改變。", 20], ["潛水寶可夢", "沉睡在很深的海溝底部。據說洛奇亞揮動翅膀的話，就會引起長達４０天的暴風雨。", 52, 1], ["虹色寶可夢", "其翅膀閃耀著七種色彩。傳說見到鳳王的人能夠擁有永遠的幸福。", 38, 1], ["時空穿越寶可夢", "從未來穿越時光而來。能夠治癒傷痛，也會把自己的力量分給草木。", 6], ["林蜥寶可夢", "腳底的小刺能鉤在牆壁或天花板上，所以就算倒掛著也不會掉下來。", 5, 1], ["林蜥寶可夢", "發達的大腿肌肉會產生出驚人的爆發力和彈跳力。", 9, 1], ["密林寶可夢", "會輕快地在叢林裡跑來跑去，並用手臂上長出的鋒利葉子解決獵物。", 17, 1], ["雛雞寶可夢", "肚子裡有火袋。抱在懷裡暖烘烘的很溫暖。只要生命尚存火焰就會持續燃燒。", 4, 1], ["幼雞寶可夢", "會發出尖銳的叫聲來提高注意力。腿技的破壞力超群。", 9, 1], ["猛火寶可夢", "遇到強敵時會從手腕噴出火焰。有著能夠躍過大樓的腳力。", 19, 1], ["沼魚寶可夢", "擁有能粉碎巨大岩石的力量。會把自己的身體埋在河底的泥土中休息。", 4, 1], ["沼魚寶可夢", "生活在粘稠泥濘的地上，久而久之就鍛煉出了強韌的腰腿。", 7, 1], ["沼魚寶可夢", "只要揮一揮如岩石般堅硬的手臂，就能將巨大的岩石打得粉碎。", 15, 1], ["緊咬寶可夢", "露出大大的獠牙猛吠威嚇對手的行為是它性格膽小的表現。", 5, 1], ["緊咬寶可夢", "會忠實聽從首領的命令。通過超群的團隊合作，絕不會讓盯上的獵物逃掉。", 10, 1], ["豆貍寶可夢", "伽勒爾的蛇紋熊適應了其他地區環境後的樣子。十分擅長找東西。", 4], ["猛衝寶可夢", "用自己超群的爆發力和銳利的爪子來制服獵物。不擅長在彎曲的道路上奔跑。", 5], ["蟲寶寶寶可夢", "非常喜歡吃葉子。受到姆克兒的襲擊時，會用尾部的刺擊退對方。", 3, 1], ["蛹寶可夢", "為了不掉下來，它將身上伸出的絲線纏在樹枝上以固定自身。然後一動不動地等待進化。", 6, 1], ["蝴蝶寶可夢", "會用細長的嘴巴刺向對手，並吸取對手的體液。生性好鬥。", 10, 1], ["蛹寶可夢", "繭內溫度非常高，渾身細胞都在裡面製造進化所需的能量。", 7, 1], ["毒蛾寶可夢", "夜行性寶可夢。被燈光引誘的毒粉蛾會把行道樹上的葉子吃得一塌糊塗。", 12, 1], ["浮萍寶可夢", "因為葉子長得太大太重，所以才會改變習性，漂浮在水面上生活。", 5], ["爽朗寶可夢", "住在日照充足的水邊。白天在水草做的床上睡覺，太陽下山後就會出來活動。", 12], ["樂天寶可夢", "樂天河童會跟著歡快的音樂搖擺身體，藉而增強自己的力量。", 15], ["橡實寶可夢", "會將頭頂黏在樹枝上懸掛著。也有被大風吹落的時候。", 5], ["捉弄寶可夢", "長鼻葉居住在大樹上的洞穴裡，牠吹奏出的草笛聲會讓聽到的人感到不安。", 10], ["邪惡寶可夢", "在森林深處靜靜地生活。據說當牠搧動大大的團扇，就會刮起冬日寒風。", 13], ["幼燕寶可夢", "有著不管是怎樣強大的對手都敢於前去迎戰的毅力。會向著溫暖的土地飛行。", 3, 1], ["燕子寶可夢", "邊在高空盤旋邊搜尋獵物，發現獵物後會頭朝下急速俯衝將其捕獲。", 7, 1], ["海鷗寶可夢", "利用氣流，不拍打翅膀就能飛上天空。會在海邊的岩壁上築巢。", 6], ["水鳥寶可夢", "會貼著海面飛行，用大大的鳥嘴連著海水一起把食物撈起來帶走。", 12], ["心情寶可夢", "用紅色的角感知到人和寶可夢的溫情後，全身也會變得有點暖暖的。", 4], ["感情寶可夢", "能夠操縱精神力量來扭曲周圍的空間，讓自己看見未來。", 8], ["包容寶可夢", "如果是為了保護訓練家，牠會不惜用盡自己的精神力量製造出小型黑洞。", 16], ["水黽寶可夢", "棲息在水草叢生的池塘或沼澤。經常和棲息地以及食物都與自己相近的滴蛛互相爭鬥。", 5], ["眼珠寶可夢", "薄薄翅膀般的觸角很容易吸收濕氣。下雨天會靜靜待在樹洞之類的地方度過。", 8], ["蘑菇寶可夢", "喜歡潮溼的地方，白天會呆在森林的樹蔭裡一動不動。會從頭上放出毒粉。", 4, 1], ["蘑菇寶可夢", "會撒出毒孢子，然後再讓因吸入孢子而苦痛不堪的對手吃上一記重拳。", 12, 1], ["懶人寶可夢", "１天要睡２０個小時。它還有一種能力是讓看著自己的對手睡意漸濃。", 8, 1], ["暴猿寶可夢", "如果不活動活動身體，壓力就會堆積過度，使身體狀況變糟。", 14, 1], ["怕麻煩寶可夢", "雖然是世界上最吊兒郎當的寶可夢，但能通過把積蓄的能量一次放出，從而發揮出驚人的力量。", 20, 1], ["入門寶可夢", "有時會在土裡生活１０年以上。會從樹木的根部吸取營養。", 5], ["忍者寶可夢", "行動十分迅速的寶可夢。說牠無論什麼攻擊都能避開也不誇張。非常喜歡甘甜的樹液。", 8], ["空殼寶可夢", "不拍動翅膀也能四處飛行。身體裡面空空的，是一種不呼吸的奇妙寶可夢。", 8], ["細語寶可夢", "一旦叫了起來，就會被自己的聲音嚇到，然後用更大的聲音大吼大叫。叫到累了就會睡著。", 6], ["大聲寶可夢", "巨大的叫聲不只會傷害聽覺，還會壓縮空氣造成衝擊波將對手震飛造成傷害。", 10], ["噪音寶可夢", "不只會大吼，還會從身上的洞發出各種音色與夥伴們彼此溝通。", 15], ["毅力寶可夢", "據說為了培育強大的幕下力士，訓練家們會製作一種傳統的火鍋料理。", 10], ["猛推寶可夢", "體型壯碩的鐵掌力士未必就很強。也有體型雖小，但身輕如燕且技巧高超的鐵掌力士存在。", 23], ["水珠寶可夢", "雖然是個性溫順的寶可夢，但生氣時就會大力揮甩尾巴上的大球來擊打對手。", 2], ["羅盤寶可夢", "牠會動也不動地用強大的磁力把獵物吸過來獵捕，但有時也會把天敵吸來。", 10], ["小貓寶可夢", "不由自主地就會去追動的東西。會追著自己的尾巴，一圈圈地原地打轉。", 6, 1], ["清高寶可夢", "有著美麗的毛髮，非常受女性訓練家的歡迎。沒有固定的住所。", 11, 1], ["黑暗寶可夢", "會去吃寶石的結晶。雙眼在漆黑一片的地方會發出寶石的光芒。", 5], ["欺騙寶可夢", "大嘴娃能用自己那由鋼角變化而成的巨大顎部將對手一口緊緊咬住。", 6], ["鐵鎧寶可夢", "進化時身上的鋼鐵盔甲會脫落。以前的人會把它撿起來用在生活上。", 4], ["鐵鎧寶可夢", "會互相碰撞身體來爭奪地盤。仔細看牠的鋼鐵盔甲，就會發現有傷痕及凹痕。", 9], ["鐵鎧寶可夢", "古時候有位國王將自己的頭盔製作成波士可多拉頭部的樣子，期盼為自己帶來像牠的強大力量。", 21], ["冥想寶可夢", "對它來說每天的瑜伽修行是不可或缺的，會通過冥想來提高精神力。", 6, 1], ["冥想寶可夢", "能夠使用通過瑜伽修行鍛煉出來的精神力量來預測對手的行動。", 13, 1], ["閃電寶可夢", "會在體毛中儲存靜電。在空氣乾燥的季節會從全身散發出火花。", 6], ["放電寶可夢", "極少在人們面前現身，據說牠的住所就在雷電落下的地方。", 15], ["加油寶可夢", "從身體撒出火花來為夥伴加油。會爬上電線杆吸取電力。", 4, 1], ["加油寶可夢", "負電拍拍和正電拍拍放出的電流有促進血液流動，緩解痠痛的功效。", 4, 1], ["螢火蟲寶可夢", "棲息在水質清澈的池塘裡。到了晚上臀部就會發光，然後它會通過那閃爍的光芒來和夥伴交流。", 7, 1], ["螢火蟲寶可夢", "會利用甜甜的香氣誘導電螢蟲在夜空中描繪２００種以上的圖形。", 6, 1], ["荊棘寶可夢", "會用右手和左手分別施放２種不同的毒來進行攻擊。香氣越濃越有活力。", 3], ["胃袋寶可夢", "它的胃能消化任何東西。消化時產生的氣體帶有強烈的惡臭。", 4, 1], ["毒袋寶可夢", "只要是大小可以放進嘴裡的東西，不管是什麼都會整個吞下。能靠特殊的胃液消化任何東西。", 17, 1], ["凶猛寶可夢", "擁有銳利的牙齒和結實的下巴。船員們絕對不會去靠近利牙魚棲息的地方。", 8], ["凶暴寶可夢", "被稱為大海惡霸。船隻要是誤闖了牠的棲息海域，無一倖免地都會被襲擊。", 18], ["球鯨寶可夢", "喝入大量的海水之後，身體會鼓成像球一樣。每天要吃掉１噸的食物。", 20], ["浮鯨寶可夢", "因為無比巨大而受歡迎。觀看吼鯨王的生態在各地都是非常受歡迎的遊覽項目。", 145], ["遲鈍寶可夢", "體內燃燒著１２００度的熔岩。一旦氣溫變低，熔岩就會凝固。動作也會因此變得遲緩。", 7, 1], ["噴火寶可夢", "平時生活在火山口。它背上的駝峰每１０年都會大爆發一次，便因而聞名。", 19, 1], ["煤炭寶可夢", "在廢棄不用的煤礦坑中住著許多的煤炭龜。牠們會不停地挖掘煤炭。", 5], ["彈跳寶可夢", "如果不保持跳動就會死亡。頭上戴著的珍珠能讓自己的精神力量增強。", 7, 1], ["操縱寶可夢", "它在操縱對手時所跳的奇異舞步，過去曾在外國掀起一陣風潮。", 9, 1], ["斑點熊貓寶可夢", "每一隻身上的斑點都不一樣。會用搖搖晃晃的動作巧妙地避開對手的攻擊。", 11], ["蟻獅寶可夢", "會建造絕對無法逃脫的缽狀巢穴，並在巢穴裡等著獵物自己掉進來。", 7], ["震動寶可夢", "為了讓翅膀成長，每天要用消化液溶化並吸食大量的獵物。", 11], ["神秘寶可夢", "由於牠揮動翅膀的聲音好似女性優美的歌聲，因此被稱為沙漠精靈。", 20], ["仙人掌寶可夢", "喜歡沙漠之類的嚴酷環境。靠體內儲存的水分可以生存３０天。", 4, 1], ["稻草人寶可夢", "會成群結隊跟在沙漠旅行者的身後，並一直等到他累得無法動彈為止。", 13, 1], ["綿鳥寶可夢", "看起來就像是團綿雲，因此不易被敵人發現。據說牠的翅膀是在一代代的演變下成為白色的。", 4], ["哼唱寶可夢", "性情溫柔，但一旦被激怒，就會用尖銳的叫聲威嚇對方，並且毫不留情地施加攻擊。", 11], ["貓鼬寶可夢", "與飯匙蛇是死對頭。一旦遇到，就會立刻張開前腳的爪子來威嚇對方。", 13, 1], ["牙蛇寶可夢", "會用堅硬的岩石來打磨刀刃般的尾巴。會躲在草叢裡，趁獵物靠近時用毒牙襲擊。", 27, 1], ["隕石寶可夢", "在４０年前隕石墜落的地點第一次被發現。瞪一眼就能使敵人沉睡。", 10], ["隕石寶可夢", "太陽能量是力量的來源，所以在白天裡很強。旋轉時身體會發光。", 12], ["鬚魚寶可夢", "會用２根長長的鬍鬚探索渾濁的河底。用濕滑的黏膜保護著身體。", 4], ["鬚魚寶可夢", "把大沼澤當成自己的地盤。敵人一旦接近就會變得十分粗暴，並引起大地震。", 9], ["無賴寶可夢", "來自外國的寶可夢，現在已經回歸了野生環境。不管多麼污濁的河水都能適應。", 6], ["流氓寶可夢", "有著熱愛戰鬥的性格。當遇到靠近自己領地的對手，會毫不留情地將之打倒。", 11], ["泥偶寶可夢", "在古代遺跡被發現。會一邊旋轉一邊移動。晚上睡覺的時候也是單腳站著。", 5], ["泥偶寶可夢", "似乎是從古代人做的泥偶誕生而來的寶可夢。能靠念力飄浮在空中移動。", 15], ["海百合寶可夢", "會吸附在海底的岩石上，並用花瓣般的觸手纏住接近自己的獵物。", 10], ["藤壺寶可夢", "用觸手捕捉到獵物時，會直接用消化液溶解獵物然後吸收養分。", 15], ["古蝦寶可夢", "會像船槳般划動８片翅膀在水中快速游動。是蟲寶可夢祖先的一種。", 7], ["甲胄寶可夢", "生活在陸地上，但也擅長游泳。會為了尋找獵物而潛入海中，用銳利的爪子解決對方。", 15], ["魚寶可夢", "雖然看起來弱小又醜陋，但擁有頑強的生命力，只要少量的水就能存活。", 6], ["慈愛寶可夢", "據說目睹了美納斯美麗身姿的人，心中一切的憤恨都能得到撫慰。", 62], ["天氣寶可夢", "樣子會隨著天氣而變化。天氣越是惡劣，性情就會變得越粗暴。", 3], ["變色寶可夢", "就算是在不需要隱身的時候，體色也會隨心情和身體狀態而改變。顏色越濃代表牠越有活力。", 10], ["人偶寶可夢", "不要去跟那些在黃昏時有怨影娃娃在排隊的人家來往。這是自古流傳下來的諺語。", 6], ["布偶寶可夢", "誕生自遭到捨棄時的怨念。據說只要讓牠感覺自己受到重視，牠就會滿意地變回原本的玩偶。", 11], ["渡魂寶可夢", "會讓身體變透明，然後偷偷地靠近獵物。擁有穿過厚牆壁的能力。", 8], ["招手寶可夢", "尋找遊盪的靈魂，吸入自己空洞的身體裡。沒人知道被吸入後會發生什麼事。", 16], ["水果寶可夢", "脖子上的美味水果很受歡迎。在溫暖的地區有很多養殖熱帶龍的牧場。", 20], ["風鈴寶可夢", "用頭部的吸盤懸掛在樹枝或是房子的屋簷下。會靈活運用７種音色。", 6, 1], ["災禍寶可夢", "由於擁有察覺危險的能力，因此牠被人們誤解是會招來災禍的寶可夢。", 12], ["開朗寶可夢", "具有集體行動的習性。睡覺的時候會在洞窟中和夥伴們把身體挨在一起。", 6], ["雪笠寶可夢", "只能在寒冷的土地上生存。即使在零下１００度的環境下也能充滿活力地到處蹦蹦跳跳。", 7], ["臉面寶可夢", "會用可讓空氣中的水分瞬間凍結的力量，將獵物冰凍起來。", 15], ["拍手寶可夢", "會漂浮在波浪間探查周圍的狀況。一旦發現獵物，就會通知群體的帝牙海獅。", 8], ["滾球寶可夢", "牠只要看見了圓形的東西，不論那是海豹球或是精靈球，都會把它頂在鼻子上轉轉看。", 11], ["破冰寶可夢", "獠牙會一輩子不停地成長。即使在戰鬥中折斷，也只需要１年的時間就又能長得巨大如初。", 14], ["雙殼貝寶可夢", "珍珠貝的珍珠非常貴重，據說價值是大舌貝所產珍珠的１０倍以上。", 4], ["深海寶可夢", "棲息在深海中。傳說如果有獵斑魚被沖上沙灘，就會有不好的事發生。", 17], ["南海寶可夢", "會吸取獵物的體液。剩下的肉會沉入海底，成為其他寶可夢的食物。", 18], ["長壽寶可夢", "在深海調查中被發現的寶可夢。樣子在１億年之間都沒有變化，被人們稱為活化石。", 10], ["相隨寶可夢", "溫暖海域的珊瑚礁是牠的棲息地。最喜歡在太陽珊瑚的枝條間睡覺。", 6], ["堅硬腦袋寶可夢", "不集結成群，而是單獨生活。擁有硬得不得了的頭部，能夠一擊就把堅硬的岩石撞成兩半。", 6], ["耐力寶可夢", "忍耐飢餓，不吃任何食物。據說當牠用盡了儲存的能量後，就會開始進化。", 11], ["龍寶可夢", "沉浸在翱翔天空的喜悅時，心情會非常好。但性情粗暴，一旦被激怒就會一發不可收拾。", 15], ["鐵球寶可夢", "身體的細胞都由磁鐵構成。在全身循環的不是血液，而是磁力。", 6], ["鐵爪寶可夢", "會以磁力在空中飛行。能在險峻的山岳中高速穿梭，將獵物逼入絕境。", 12], ["鐵足寶可夢", "２隻金屬怪組合起來的樣子。會發揮堪比超級電腦的智能去打倒敵人。", 16], ["岩山寶可夢", "有人利用最新的科學技術調查了牠的岩石身體，但卻找不到牠的大腦或心臟。", 17], ["冰山寶可夢", "全身都是由冰塊構成。據說牠是在冰河時期誕生在厚實的冰層下。", 18], ["黑金寶可夢", "據說牠誕生於地底的地幔中，並且在大約１萬年前出現在地表。", 19], ["無限寶可夢", "通過心靈感應交流情感。用能令光發生折射的羽毛包裹身體來讓自己隱形。飛行能力和攻擊力提升。會撒下透明的羽毛擾亂敵人。（超級進化）", 14, 1], ["無限寶可夢", "擁有很高的智商，能理解人類的語言。是討厭爭鬥且溫柔的寶可夢。飛行速度超過４馬赫。擁有在寶可夢中頂級的空中戰鬥力。（超級進化）", 20, 1], ["海底寶可夢", "神話中的寶可夢，它用大雨和大海嘯擴張海洋。曾與固拉多激烈交戰。通過擁有原始世界的能量的靛藍色寶珠迴歸而來。肉體就像是海水一樣。（原始迴歸）", 45, 1], ["大陸寶可夢", "據說能用高溫蒸發水分擴張大地。曾與蓋歐卡激烈交戰。藉由硃紅色寶珠復活的原本的樣子。能量化作岩漿，從身體裡面溢出。（原始迴歸）", 35, 1], ["天空寶可夢", "因為棲息在高高的雲層之上的臭氧層，所以從地面無法看見它的樣子。夜空中閃耀的流星可能是超級烈空坐追逐隕石飛舞的身姿。（超級進化）", 70, 1], ["祈願寶可夢", "傳說當牠從１０００年的沉睡中醒來時，會實現寫在牠頭部許願箋上的願望。", 3], ["ＤＮＡ寶可夢", "附著在隕石上的宇宙病毒的ＤＮＡ變異後生成的寶可夢。", 17, 1], ["嫩葉寶可夢", "觸摸背上由泥土構成的甲殼時，如果感覺到溼潤度適中，就證明那隻草苗龜非常健康。", 4, 1], ["樹叢寶可夢", "據說生活在森林的樹林龜有著自己才知道位置的清澈湧泉。", 11, 1], ["大陸寶可夢", "在遙遠的過去，人們曾假想過，在大地的下面存在著巨大土臺龜。", 22, 1], ["小猴寶可夢", "身輕如燕的寶可夢。為了不點燃附近的東西，會先滅掉屁股上的火焰再睡覺。", 5, 1], ["頑皮寶可夢", "能熟練控制尾部火焰的大小，以自己擅長的距離進行戰鬥。", 9, 1], ["火焰寶可夢", "用速度玩弄對手。會使用手腳並用的獨特戰鬥方式。", 12, 1], ["企鵝寶可夢", "不擅長走路，有時還會跌到，但波加曼強烈的自尊心會讓它挺起胸膛，毫不在意。", 4, 1], ["企鵝寶可夢", "不結交夥伴，獨自生活。翅膀的強烈一擊能把大樹一劈兩半。", 8, 1], ["皇帝寶可夢", "傷害到它自尊心的傢伙，會被它用能切斷浮冰的翅膀一分為二。", 17, 1], ["椋鳥寶可夢", "以龐大的群體在山野間飛來飛去，追捕蟲寶可夢。叫聲非常吵鬧。", 3, 1], ["椋鳥寶可夢", "對自己的弱小心知肚明，所以平時總是群體生活。獨處時會發出吵鬧的叫聲。", 6, 1], ["猛禽寶可夢", "變為姆克鷹後，就會脫離群體獨自生活。擁有強韌的翅膀。", 12, 1], ["圓鼠寶可夢", "遇到任何事都不慌不忙，神經很大條的傢伙。能做出與外表不符的靈敏動作。", 5, 1], ["河狸寶可夢", "用樹幹和泥巴築壩堵住河流，建造住所。以勤勞而聞名。", 10, 1], ["蟋蟀寶可夢", "每當腿短的它快要跌倒時，堅硬的觸角就會互相摩擦，發出如木琴般的聲音。", 3, 1], ["蟋蟀寶可夢", "通過讓聲音在體內的空洞迴響來使自己的叫聲變得悅耳。", 10, 1], ["閃光寶可夢", "體毛通電就會發光。會揮動明亮發光的尾巴前端來向夥伴打信號。", 5], ["電光寶可夢", "遇見敵人時會從腳伸出有百萬伏特威力的爪子，為對戰做好準備。", 9], ["目光寶可夢", "由於透視會消耗極大量的電能，因此牠會花很長的時間睡覺，藉此儲存能量。", 14], ["花苞寶可夢", "對氣溫的變化很敏感。當牠開始打開花苞，便是冬去春來之時。", 2], ["花束寶可夢", "右手的毒是速效的，左手的毒則是慢性的。無論哪邊的毒性都能致命。", 9], ["頭錘寶可夢", "特徵是堅硬的頭蓋骨。會用頭錘撞斷樹木，吃樹上長的樹果。", 9], ["頭錘寶可夢", "擅長頭錘的古代寶可夢。因為大腦真的很小，所以也有說法認為牠是因為太笨而滅亡的。", 16], ["護盾寶可夢", "雖然在遠古時代的地層中發現了牠的化石，但至今未曾發現臉部以外的部分。", 5], ["護盾寶可夢", "大約１億年前的寶可夢。結實到極點的臉擁有超越鋼鐵的硬度。", 13], ["蓑衣蟲寶可夢", "為了抵禦寒冷的秋風，會用小樹枝和落葉當材料，做成蓑衣裹在身上。", 2, 1], ["蓑衣蟲寶可夢", "從結草兒進化過來時，蓑衣成為了身體的一部分。一輩子都不會脫下蓑衣。", 5, 1], ["蓑衣蛾寶可夢", "非常喜歡吃花蜜。會搶奪三蜜蜂採集到的蜜，然後自己吃掉。", 9, 1], ["幼蜂寶可夢", "從早到晚都在採集花蜜。這一切都是為了自己的族群和蜂女王。", 3], ["蜂巢寶可夢", "能釋放越多費洛蒙的蜂女王，就能讓越多的三蜜蜂聽從自己的指揮。", 12], ["電松鼠寶可夢", "", 4], ["海鼬寶可夢", "像螺旋槳一樣旋轉著尾巴，不僅能讓它在水裡游泳，還能切斷纏住自己的海草。", 7, 1], ["海鼬寶可夢", "浮囊膨脹起來後，就能讓人乘坐在背上。會排出浮囊的氣來潛水。", 11, 1], ["櫻桃寶可夢", "身體越紅的櫻花寶含有的營養越豐富，味道也很甜很好吃。", 4], ["櫻花寶可夢", "闔起來的花瓣很硬。即使被鳥寶可夢啄到，也完全沒問題。", 5], ["海兔寶可夢", "如果用力按住牠，牠就會分泌出神秘的紫色液體。雖然液體無害，不過黏糊糊的。", 3], ["海兔寶可夢", "身體軟綿綿的但十分強韌。因為牠身體的軟度可以幫助牠分散所受到的衝擊。", 9], ["長尾寶可夢", "不管做什麼事都會用到尾巴。如果牠用２根尾巴抱緊你，就代表牠真的和你很親近。", 12], ["氣球寶可夢", "因魂魄聚集在一起而誕生。到了濕氣重的季節就有可能大量出現。", 4], ["熱氣球寶可夢", "會抓住人和寶可夢，然後運到某個地方。沒人知道那地方是哪裡。", 12], ["兔子寶可夢", "會利用把捲成團的耳朵伸直時的威力來使出攻擊招式。越訓練，招式威力就會越大。", 4], ["兔子寶可夢", "炎熱的季節結束後，就會換上富含空氣的體毛以備寒天來臨。", 12], ["魔法寶可夢", "會喃喃唸誦詛咒的話語，使對手激烈頭痛，或是看見恐怖的幻覺，藉此折磨對手。", 9], ["大頭目寶可夢", "與敵人的戰鬥幾乎全由手下來應付。只有在最後給對手致命一擊的時候，才會弄髒自己的手。", 9], ["裝乖寶可夢", "一不稱心，就會豎起爪子。但偶爾會從喉嚨裡發出聲響來撒嬌，這樣的性格很受部分人喜愛。", 5, 1], ["虎斑貓寶可夢", "臉皮極厚，即使是其他寶可夢的住處，也會大搖大擺地進去睡起覺來。", 10, 1], ["鈴鐺寶可夢", "如果跳起來，嘴裡的珠子就會彈來彈去，發出鈴鐺一般的音色。", 2, 1], ["臭鼬寶可夢", "要是牠翹起尾巴把屁股對準了你，請一定要小心。因為這表示牠將要噴出足以讓人窒息的臭液。", 4], ["臭鼬寶可夢", "從尾巴尖端噴出的液體帶有強烈的惡臭。會在地面上挖洞建造巢穴。", 10], ["青銅寶可夢", "雖然人們說把銅鏡怪打磨到發光，牠就能映照出真相，但其實牠非常討厭被打磨。", 5], ["銅鐘寶可夢", "牠身上的紋路讓許多學者認為牠原本並不存在於伽勒爾。", 13], ["盆栽寶可夢", "棲息在空氣乾燥岩石裸露的地方。空氣越是乾燥，牠身上的綠球就越是會泛出黯淡的光澤。", 5], ["默劇寶可夢", "像徒弟一樣跟隨著擅長跳舞的踏冰人偶，拼命模仿牠的舞步。", 6], ["家家酒寶可夢", "會把寶貝的渾圓石頭借給變得友好的對象。如果不還給牠的話，就會哭著大鬧。", 6], ["音符寶可夢", "學習人類的語言來鳴叫。當夥伴們聚集在同一個地方時，大家就會學習到同樣的詞彙。", 5, 1], ["封印寶可夢", "總是作惡多端，不料有一天被使用神奇法術的旅人綁縛到了楔石上。", 10], ["陸鯊寶可夢", "會不分青紅皂白地襲擊會動的東西，將對方拖進自己睡覺的小洞裡。雖然嘴巴很大，但胃卻算是小的。", 7], ["洞穴寶可夢", "會把寶石埋藏在自己棲息的洞窟裡。但只要入侵牠的洞窟，就會立刻被牠的爪子和牙齒撕碎。", 14], ["音速寶可夢", "在陸地上也能迅速行動。會在身體被寒冷的雪山凍僵之前了結獵物並返回住處。", 19], ["大胃王寶可夢", "在體毛下儲存食物。如果是自己信賴的對象，也會把食物分給對方一口。", 6], ["波紋寶可夢", "除了能讀懂對手的感情，也能以「波導」這種形式的波來觀察大自然的樣子。", 7], ["波導寶可夢", "牠能理解人類的想法，因此只會去親近內心端正的訓練家。", 12], ["河馬寶可夢", "主要在白天活動。因為沙漠的夜晚會降溫，所以會鑽進沙子的深處睡覺。", 8], ["重量寶可夢", "生氣的時候非常凶暴。會噴出儲存在體內的沙子來引發沙塵暴。", 20], ["蠍子寶可夢", "用尾巴上帶毒的鉤爪襲擊對手。一旦被夾住，毒素就會擴散開來，導致全身無法動彈。", 8], ["蠍怪寶可夢", "雖然猙獰凶猛到被人們稱為沙之惡魔，但在河馬獸面前卻表現得低調溫順。", 13], ["毒擊寶可夢", "毒素在稀釋後能製成藥品。牠是製藥公司的吉祥物，廣受眾人的歡迎。", 7], ["毒擊寶可夢", "制服了獵物之後，便會呱呱地發出勝利的歡呼。與蟾蜍王是相近的物種。", 13], ["捕蟲寶可夢", "先用甜香的唾液引誘獵物，然後用大顎大口地嚼。要花１整天吃掉獵物。", 14, 1], ["飛翅魚寶可夢", "會用發光的尾鰭引誘獵物。白天會待在海面附近，到了夜裡就會向深海移動。", 4], ["霓虹寶可夢", "像爬行般地在海底游動。鰭發出的光充滿奇幻氣氛，就像夜空中的星星一樣。", 12], ["風箏寶可夢", "混在鐵炮魚的大群裡游泳。受到敵人襲擊的時候，會和鐵炮魚們並肩作戰。", 10], ["樹冰寶可夢", "雪笠怪肚子上結出來的樹果口感彷如冰棒，是伽勒爾的火紅不倒翁們的最愛。", 10], ["樹冰寶可夢", "會引發暴風雪的寶可夢。只要牠搖動巨大的身體，周圍立刻會變得一片雪白。", 22], ["鉤爪寶可夢", "透過用爪子留下記號來與夥伴聯絡。據說記號的種類有５００種以上。", 11], ["磁場寶可夢", "人們認為牠是受到特殊磁場的影響，導致身體的分子結構發生變化才進化的。", 12], ["舔舔寶可夢", "舌頭靈巧得不輸人類的手，什麼事情都能用它來完成。相對地，手指倒是很笨拙。", 17], ["鑽錐寶可夢", "用護具彈開敵人的攻擊，在對手畏縮時用自己引以為傲的鑽頭貫穿對方。", 24], ["藤蔓狀寶可夢", "棲息的地方越溫暖，藤蔓就會長得越快。當藤蔓變得太長時，就會自己扯斷它來調整長度。", 20], ["雷電寶可夢", "發電量在電氣寶可夢中是屬於最頂級的。會從尾巴的前端放出高壓電流。", 18], ["爆炎寶可夢", "長久棲息在火山口，使得牠的身體變得像是一座火山，甚至擁有類似岩漿庫的器官。", 16], ["祝福寶可夢", "被稱為帶來恩惠的寶可夢，從很久很久以前開始，人們就視牠為吉祥之物。", 15], ["勾蜓寶可夢", "拍動翅膀的力量極強，在用力起飛時，會掀倒周圍的巨樹。", 19, 1], ["新綠寶可夢", "尾巴如同銳利的刀刃，鋒利得無與倫比，連大樹都能一刀兩斷。", 10], ["新雪寶可夢", "冰伊布釋放出的冷氣能製造出粉狀的雪。這使牠受到各個滑雪場的熱烈歡迎。", 8], ["牙蠍寶可夢", "只要順利乘上微風，哪怕一次翅膀都不拍，也能環繞這個星球一週。", 20, 1], ["雙牙寶可夢", "牠的力量就如外表那樣強大。天氣越是寒冷，牠的冰牙就會長得越粗、越長、越結實。", 25], ["虛擬寶可夢", "據說是在追加程式後進化了，但牠的改變是否真的是進化，在學術界也是意見分歧。", 9], ["利刃寶可夢", "能夠敏銳地感知到尋求幫助的感情，並且火速趕去援助對方。", 16], ["羅盤寶可夢", "會驅使３個小組件去獲取食物或與敵人戰鬥。本體基本上只負責下命令。", 14], ["抓握寶可夢", "用腹部的嘴將獵物整個吞下。只會吃掉對方的魂魄，離去時會把肉體吐出來。", 22], ["雪國寶可夢", "會吐出零下５０度的冷氣凍住獵物，並把牠們帶回自己的巢穴，整齊地擺成一排。", 13], ["等離子寶可夢", "會用等離子構成的身體潛入各式各樣的機器裡。最喜歡惡作劇嚇人。", 3], ["知識寶可夢", "被稱為知識之神。據說擁有消除與之目光交會者的記憶的力量。", 3, 1], ["感情寶可夢", "教會了人們悲傷的痛苦和快樂的寶貴。被稱為感情之神。", 3, 1], ["意志寶可夢", "被稱為意志之神。一直沉睡在湖底，維持著世界的平衡。", 3, 1], ["時間寶可夢", "擁有操縱時間的力量，在神奧地區的神話裡被描述成神。", 54, 1], ["空間寶可夢", "擁有扭曲空間的能力，在神奧地區的神話裡被描述成神。", 42, 1], ["火山口寶可夢", "像熔岩般沸騰的血液在體內流動著。棲息在火山的洞穴裡。據說它在火力全開時體溫會升高到１００萬度，決不允許敵人靠近。（超級進化）", 17, 1], ["巨大寶可夢", "據說牠曾使用各種材料製作了寶可夢，然後把大陸移動到了現在的位置。", 37], ["反抗寶可夢", "據說這種寶可夢棲息在位於這個世界背面的世界裡。會出現在古代的墓地中。", 45, 1], ["新月寶可夢", "飛行的時候，會從薄紗一樣的翅膀中發出閃光粒子。被稱為新月的化身。", 15, 1], ["海洋寶可夢", "棲息在溫暖的海里。會讓頭部的浮囊膨脹起來，漂浮在波濤間尋找食物。", 4, 1], ["洄游寶可夢", "出生於冰冷的海底。為了回到自己出生的海底，它會游上非常長的距離。", 3, 1], ["暗黑寶可夢", "擁有誘使人們進入深度睡眠並做夢的能力。在朔月的夜晚活動。黑暗力量會遮蔽太陽，使周圍全部陷入黑暗。誰都無法逃離它的邪眼。（超級進化）", 15, 1], ["感謝寶可夢", "生活在花圃中，只要把身體蜷成團，看起來就像花一樣，任誰都察覺不到。", 2, 1], ["創造寶可夢", "神話裡將它描述為用１０００隻手創造了宇宙的寶可夢。", 32, 1], ["勝利寶可夢", "是會帶來勝利的寶可夢。據說帶著比克提尼的訓練家會贏得任何對戰。", 4, 1], ["草蛇寶可夢", "當尾巴的葉子受到日照製造出能量後，動作就會變得敏捷，招式也會更加強勁。", 6, 1], ["草蛇寶可夢", "", 8], ["皇家寶可夢", "能將由陽光製造出的能量在長長的身體內增強至原本的數十倍。", 33, 1], ["火豬寶可夢", "能以有別外表的輕巧動作玩弄敵人。可從左右兩個鼻孔連續發射出火球。", 5, 1], ["火豬寶可夢", "戰鬥時會熱血沸騰。體溫會急速上升，然後變成灼熱的火球。", 10, 1], ["大火豬寶可夢", "在胸內熊熊燃燒的火焰從顎部猛烈地噴出，形成了火焰的鬍鬚。", 16, 1], ["海獺寶可夢", "會把腹部的扇貝貝如同小刀般使用，接了敵人的招式後會立馬切斬反擊。", 5, 1], ["修行寶可夢", "它將２枚扇貝貝運用得行雲流水的動作，據說被人們當作了劍術的範本。", 8, 1], ["威嚴寶可夢", "拔刀術的高手。會用收在前腿鎧甲裡的大刀一劍定勝負。", 15, 1], ["放哨寶可夢", "會在頰囊裡藏食物，連續放哨好幾天。用尾巴給夥伴發出暗號。", 5, 1], ["警戒寶可夢", "用體內的發光物質讓眼珠和身體閃閃發光，使來襲的敵人畏縮。", 11, 1], ["小狗寶可夢", "比一般的小孩子都還要聰明。對於自己得到的關愛，或是受到的傷害牠都不會忘記。", 4], ["忠犬寶可夢", "覆蓋身體的黑色體毛既厚實又有彈性，就連銳利的獠牙也會被反彈。", 9], ["寬大寶可夢", "以氣派的鬍鬚為傲的寶可夢。據說在夥伴之間的階級地位就取決於鬍鬚的長度。", 12], ["壞心眼寶可夢", "會用可愛的動作讓對手放下戒心，趁對方靠過來時冷不防用爪子猛抓，然後得意地大笑。", 4], ["冷酷寶可夢", "和狐大盜爭搶地盤。能夠悄無聲息地從背後偷偷靠近獵物。", 11], ["草猴寶可夢", "會把頭上的葉子分給沒有精神的寶可夢。具有緩解疲勞的效果。", 6, 1], ["刺猴寶可夢", "性格粗暴，會揮動著帶有尖刺的尾巴戰鬥。頭上的葉子非常苦。", 11, 1], ["高溫寶可夢", "智商很高，有著將樹果烤熟後再吃的習性。很喜愛給人類幫忙。", 6, 1], ["火花寶可夢", "興奮的時候，從頭和尾巴飛揚起火花，身體變熱。不知為何，很喜歡吃甜的東西。", 10, 1], ["潑水寶可夢", "頭上的毛髮叢裡儲藏的水充滿了營養。會用尾巴給草木澆這種水。", 6, 1], ["放水寶可夢", "喜歡水很乾淨的地方。一旦頭上儲藏的水減少，就會用尾巴吸水來補充。", 10, 1], ["食夢寶可夢", "在吃掉夢之後會吐出煙霧。吃了快樂的夢時，煙霧是粉紅色的；如果是惡夢，煙霧則是黑灰色的。", 6], ["半夢半醒寶可夢", "總是在打瞌睡作夢。剛睡醒的時候會鬧脾氣，所以最好別去招惹牠。", 11], ["小鴿寶可夢", "雖然既健忘又不太聰明，因為性格認真且容易親近人，所以受到了許多訓練家的喜愛。", 3], ["野鴿寶可夢", "頭腦聰明且記性很好。似乎有許多快遞員將牠選為自己的搭檔。", 6], ["自尊心寶可夢", "頭腦聰明，所以自尊心也強。如果能成為高傲雉雞的訓練家，所有人都會對你刮目相看。", 12], ["帶電寶可夢", "用心跳來發電。受驚導致心跳加速時，電壓也會隨之上升。", 8, 1], ["雷電寶可夢", "性格暴躁充滿攻擊性。興奮起來時，就會讓鬃毛亮起黃色光芒並放出電擊。", 16, 1], ["地幔寶可夢", "會對聲音產生反應而動起來。在能量核心的影響下，牠摸起來暖暖的。", 4], ["礦石寶可夢", "透過聲音來探測四周。要是惹牠生氣了，牠會連身體方向也不轉就朝你追來。", 9], ["高壓寶可夢", "牠射出的能量彈具有能擊飛砂石車的破壞力。不過只有在晴天才能射擊。", 17], ["蝙蝠寶可夢", "一邊發出超音波，一邊飛來飛去尋找蟲寶可夢來填飽自己的肚子。", 4], ["求愛寶可夢", "據說有些地區的人覺得牠鼻子的形狀很吉利，而把牠當成幸福的象徵來祭拜。", 9], ["鼴鼠寶可夢", "會用爪子在地底挖掘前進。一些農民因為擔心牠會因此糟蹋蔬菜而討厭牠。", 3], ["地底寶可夢", "別名鑽頭王。在地底下挖掘前進的速度高達每小時１５０公里。", 7], ["聽力寶可夢", "心地善良的寶可夢。透過用觸角觸碰，就能了解對方的情緒和身體狀況。", 11], ["筋骨寶可夢", "如果搬運小匠可以搬起自己體重３倍左右的木材，就代表牠進化的日子要到了。", 6], ["筋骨寶可夢", "能夠靈巧地操縱鋼骨。雖然對拆除得心應手，但卻不太擅長組裝。", 12], ["筋骨寶可夢", "要是認真起來就會扔掉手中的混凝土柱，赤手空拳地撲向敵人。", 14], ["蝌蚪寶可夢", "透過音波來聯繫夥伴。人類和其他寶可夢都聽不見牠發出的警告聲。", 5], ["震動寶可夢", "有時也會發出悅耳的叫聲。身上突起物越大的藍蟾蜍越能以更廣的音域來鳴叫。", 8], ["震動寶可夢", "在老年人之間廣受歡迎。因為他們覺得牠身上的瘤發出的震動拿來按摩剛剛好。", 15], ["柔道寶可夢", "５隻一組一起努力練習。在練習中掉隊的投摔鬼會扔掉帶子離開團隊。", 13], ["空手道寶可夢", "不斷重複練習的打擊鬼所使出的空手劈擁有足以劈開大海的破壞力。", 14], ["裁縫寶可夢", "會仿照保姆蟲為它穿上的葉子衣服，有樣學樣地啃咬樹葉製作衣服。", 3, 1], ["足不出葉寶可夢", "會在樹木根部靜靜生活。比起新鮮的葉子，更愛吃變軟的落葉。", 5, 1], ["育兒寶可夢", "性格溫厚且保護欲強。葉子般的手臂鋒利得能將大樹一刀兩斷。", 12, 1], ["蜈蚣寶可夢", "牙齒有劇毒。一旦發現了看似能吃下肚的獵物，就會不加思索地撲上去。", 4], ["繭蜈蚣寶可夢", "用堅硬的殼和有毒的刺保護自己，同時累積進化所需的能量。", 12], ["巨蜈蚣寶可夢", "為了搶地盤，會和焚焰蚣激烈地爭鬥。輸掉的那一方會直接變成對手的獵物。", 25], ["棉球寶可夢", "將木棉球和白蓬蓬的棉花混合後編織出的布料極其精緻，因此常被高級品牌選用。", 3], ["風隱寶可夢", "每當沐浴陽光，身上的棉花就會膨脹。如果膨脹過了頭，牠就會把棉花扯開到處亂撒。", 7], ["根莖寶可夢", "葉子的顏色越深就越健康。有時也會在整理得很好的田地或花壇定居下來。", 5], ["花飾寶可夢", "由牠的花朵提煉的精油有著極致的香氣，但價格同時也是貴得令人眼睛幾乎要掉出來。", 11], ["粗暴寶可夢", "從前也曾經登上餐桌。紅條紋野蠻鱸魚的肉脂肪含量高，適合年輕人食用。", 10], ["沙漠鱷魚寶可夢", "體型雖小，但下盤很有力。會撥開沙子，在沙漠中像是游泳般地自在移動。", 7], ["沙漠鱷魚寶可夢", "雖然有一雙在漆黑環境也能看見四周的特殊眼睛，但因為沙漠的夜晚較寒冷，所以牠不太會活動。", 10], ["威嚇寶可夢", "雖然凶暴，但同時也具有很強的忍耐力。為了捕捉獵物能在沙子裡等上很多天。", 15], ["不倒翁寶可夢", "在牠睡覺的時候，無論是推是拉，牠都不會倒下。因為象徵著吉利而大受歡迎。", 6], ["爆燃寶可夢", "體內的火焰燃得越旺，力量就越大。火焰的溫度有時甚至能超過１４００度。", 13], ["仙人掌寶可夢", "一年散播一次種子。花的種子營養十足，是沙漠中貴重的食糧。", 10], ["石居寶可夢", "如果找不到大小合適的石頭來當成自己的家，牠也會住到河馬獸的洞裡。", 3], ["岩居寶可夢", "厚實的鉗子是牠最大的武器。硬度高到甚至能讓超甲狂犀的護具裂開。", 14], ["蛻皮寶可夢", "用結實的皮保護身體。據說在皮伸展到極限時，牠就會開始進化。", 6], ["惡黨寶可夢", "雖然性情非常粗魯，但也有重視家族、夥伴和地盤的一面。", 11], ["似鳥寶可夢", "人們在象徵鳥飛過的沙漠地下進行調查，結果在那裡發現了疑似古代都市的遺跡。", 14], ["魂寶可夢", "古代人的靈魂變成了寶可夢。為了尋找認得自己長相的人而在遺跡裡徘徊。", 5], ["棺木寶可夢", "死神棺象徵著國王的財富，因此許多古墓裡都有牠的壁畫。", 17], ["古代龜寶可夢", "從化石復原的寶可夢。被認為是許多的龜寶可夢的祖先。", 7], ["古代龜寶可夢", "雖然和水中相比動作會變得比較遲緩，但為了尋找獵物牠還是會在陸地上活動。", 12], ["遠古鳥寶可夢", "被稱作是鳥寶可夢的祖先。棲息在樹上，以樹果和蟲寶可夢為食。", 5], ["遠古鳥寶可夢", "雖然能夠飛行，但牠似乎更擅於在地上捕捉獵物。", 14], ["垃圾袋寶可夢", "誕生自塞滿垃圾的垃圾袋裡。牠嘴裡噴出的毒氣是伽勒爾雙彈瓦斯的最愛。", 6], ["垃圾場寶可夢", "從右臂噴出的毒液十分危險，虛弱的生物只要一沾到，立刻就會丟掉性命。", 19], ["惡狐寶可夢", "為了尋找食物，有時還會幻化成人類出現在城鎮裡。通常都會變成小孩子。", 7], ["妖狐寶可夢", "孤獨的訓練家會命令索羅亞克讓他看見幻影，藉此紓解一個人的寂寞。", 16], ["栗鼠寶可夢", "用尾巴互相撫摸來打招呼。尾巴的毛比較蓬鬆的那一方會表現得稍微威風些。", 4], ["圍巾寶可夢", "覆蓋著特別油脂的毛髮可以擋住攻擊。這種油以高價在市場上流通。", 5], ["凝視寶可夢", "哥德寶寶會在看似無人的地方輕聲地叫。牠好像是在與某種只有牠才看得見的東西說話。", 4], ["操縱寶可夢", "哥德小童的精神力量似乎會在星光閃耀的夜晚達到最高點。牠與宇宙的關係至今不明。", 7], ["天體寶可夢", "從哥德小姐那裡看到了自己下場的惡人在那之後便銷聲匿跡了。", 15], ["細胞寶可夢", "身體被特殊的液體包裹著，許多人因此認為牠即使在宇宙中也能存活。", 3], ["分割寶可夢", "由於牠一分為二的大腦思考的內容幾乎完全不同，導致牠的行動非常難以預測。", 6], ["增幅寶可夢", "雖然有人說只要喝掉牠特殊的液體就能得到智慧，但對人造細胞卵以外來說，那其實是劇毒。", 10], ["水鳥寶可夢", "還不擅長飛行。會看著雙親舞天鵝跳舞來學習如何拍動翅膀。", 5, 1], ["白鳥寶可夢", "會以群體的首領為中心，跳出絲絲入扣的舞蹈來提升凝聚力哦。", 13, 1], ["新雪寶可夢", "據說牠是從冰柱中誕生的。為了能讓自己生活得更舒適，會吐出零下５０度的冷氣凍住四周。", 4], ["冰雪寶可夢", "性情和善，雖然會用零下１００度的冷氣凍住敵人，但並不會傷及牠們的性命。", 11], ["暴風雪寶可夢", "體溫在零下６度左右。據說是由２隻多多冰黏在一起而誕生的。", 13], ["季節寶可夢", "氣味會隨著季節而改變，初春的氣味略帶甘甜，能使情緒穩定下來。（春天的樣子）為了防止田地被它入侵，許多農家會拜託它的天敵，也就是鬃巖狼人來站崗。（夏天的樣子）它擁有毫不怕生的性格，因此在人類面前也是我行我素。只要給它食物就能立刻拉近關係。（秋天的樣子）四季鹿的體味會隨季節而變，但當它是冬天的樣子時，卻幾乎沒有任何氣味。（冬天的樣子）", 6, 1], ["季節寶可夢", "角上的花很多的萌芽鹿由於會被花搶走養分，從而成長速度略顯緩慢。（春天的樣子）擁有很多愛好者的寶可夢。人們認為它角上的枝葉越厚越大就代表越雄偉。（夏天的樣子）擁有很多愛好者的寶可夢。人們認為它角上垂下的枝葉越紅就代表越氣派。（秋天的樣子）當它是這個樣子時會比較穩重，容易馴化，是與它成為同伴的好機會。（冬天的樣子）", 19, 1], ["飛鼠寶可夢", "最喜歡甜甜的樹果。有時會因為在頰囊裡儲存了太多食物，結果讓自己無法好好飛行。", 4], ["啃咬寶可夢", "用嘴裡吐出的液體來融化小嘴蝸的殼，只會去吃裡面的身體。", 5], ["騎兵寶可夢", "會舉起長矛突擊敵人。有一幅名畫描繪著牠和蔥遊兵決鬥的場景。", 10], ["蘑菇寶可夢", "從雙臂噴出的孢子是劇毒，但據說在徹底乾燥之後，可以作為腸胃藥使用。", 2], ["蘑菇寶可夢", "平時不太會有動作。只是一動也不動地待在地上掉落的精靈球旁邊。", 6], ["漂浮寶可夢", "據流傳至今的傳說所述，牠是由沉沒到海底的古代都市的居民變成的寶可夢。", 12], ["漂浮寶可夢", "每到滿月時，胖嘟嘟會成群結隊地來到海面上。這麼做是為了等待獵物上門。", 22], ["看護寶可夢", "之所以救助衰弱的寶可夢，好像是因為自己也會被盯上牠們的寶可夢襲擊。", 12], ["吸附寶可夢", "會附在其他寶可夢身上吸取靜電。經常會把自己貼在來電汪的屁股上。", 1], ["電蜘蛛寶可夢", "為了捕捉不太會飛的幼鳥，會在鳥寶可夢的巢穴附近用帶電的絲設下陷阱。", 8], ["刺果寶可夢", "偏愛長著青苔的洞窟。青苔中所含的酵素能使牠的尖刺成長得又大又結實。", 6], ["刺球寶可夢", "擁有比鋼鐵還堅硬的尖刺。會利用觸手上的尖刺攀附在岩壁上移動。", 10], ["齒輪寶可夢", "據說在很久以前，是看到了齒輪兒的人發明了齒輪的構造。", 3], ["齒輪寶可夢", "被認為是工業技術的象徵。有許多伽勒爾當地的公司選擇牠作為企業的標誌。", 6], ["齒輪寶可夢", "讓３個齒輪高速旋轉。新增出來的那個帶著尖刺的齒輪並不是生物。", 6], ["電魚寶可夢", "１條的電力雖小，但是許多麻麻小魚聚在一起，其威力可以比得上雷電。", 2, 1], ["電魚寶可夢", "圓圓的花紋是發電器官。會先纏住對手，然後把花紋壓在對手身上後放出電流。", 12, 1], ["電魚寶可夢", "用手臂的力量從海里爬出，襲擊水邊的獵物。在一瞬間將對方拖入海中。", 21, 1], ["腦寶可夢", "在大約５０年前被發現的寶可夢。會用又大又發達的大腦來操縱精神力量。", 5], ["腦寶可夢", "能控制對方的記憶。經常有人看到牠在麥田的上方徘徊。", 10], ["蠟燭寶可夢", "吸取到的靈魂越年輕，頭上的燭光就會燃燒得越旺越詭異。", 3], ["油燈寶可夢", "偽裝成燈的樣子藏身在城鎮裡。一旦發現了臨近死期的人，便會悄悄地跟在後面。", 6], ["引誘寶可夢", "據說在用水晶燈火靈來充當照明設備的房子裡，喪事會接連不斷。", 10], ["牙寶可夢", "會和夥伴們一起互撞牙齒來玩。折斷的牙齒會馬上長出來，所以絲毫都不會在意。", 6], ["顎斧寶可夢", "皮膚像盔甲一樣堅硬。非常擅長在撞擊的同時用牙齒猛刺的戰法。", 10], ["顎斧寶可夢", "性情溫和，但生起氣來非常恐怖。會用自己那引以為傲，可以削鐵如泥的牙齒攻擊敵人。", 18], ["結冰寶可夢", "使出招式前會先倒吸鼻涕。鼻涕裡所含有的強烈冷氣是冰屬性招式的能量來源。", 5], ["凍結寶可夢", "在冰冷的大海裡精力十足地游泳。感到疲勞的時候會吐出氣息凍結海水，在冰面上休息。", 26], ["結晶寶可夢", "天氣一熱，就會變成水蒸氣。在夏天見到牠的機會少之又少。", 11], ["蝸牛寶可夢", "有著會對電能產生反應的奇異體質。不知為何，和蓋蓋蟲待在一起就會進化。", 4], ["脫殼寶可夢", "脫殼後變得更輕巧了。為了防止乾燥，會將帶狀的黏膜裹在身上。", 8], ["陷阱寶可夢", "當從身上的黃色斑紋裡釋放出強大電流時，牠會莫名地露出微笑。", 7], ["武術寶可夢", "個頭雖小，個性粗暴。對於漫不經心就靠近自己的對手會奉上華麗的連擊。", 9], ["武術寶可夢", "快到無法看清的踢腿非常強烈，即使是巨大的岩石也能粉碎。", 14], ["洞穴寶可夢", "性情凶暴且狡猾。會搶奪其他寶可夢挖好的巢穴，來當作是自己的窩。", 16], ["魔像寶可夢", "用黏土製成的寶可夢。即使現在也一直遵循著數千年前主人的命令。", 10], ["魔像寶可夢", "雖然有人認為牠體內有著生成能量的永動機，但至今仍未得到證實。", 28], ["利器寶可夢", "以劈斬司令為首領組成族群。目標是有朝一日能統領同類，所以每天都在不懈地鍛鍊。", 5], ["刀刃寶可夢", "為了搶佔能找到磨刀石的地方，和斧牙龍展開了激烈的鬥爭。", 16], ["頭錘牛寶可夢", "會組成約２０隻的群體一起生活。不知為何，背叛了群體的爆炸頭水牛頭上的毛會脫落。", 16], ["雛鷹寶可夢", "握力強，能把堅硬的樹果弄得粉碎。性急愛吵架，無論對誰都會挑起戰鬥。", 5], ["勇猛寶可夢", "性情粗暴、血氣方剛，因此被鋼鎧鴉奪走了伽勒爾運送員的地位。", 15], ["尿布寶可夢", "由於很快就會長大，屁股上的骸骨會接著傳給巢裡更小的禿鷹丫頭用。", 5], ["骨鷹寶可夢", "把撿來的骨頭裝飾在身上。在骨頭形狀這方面似乎也是有流行趨勢的。", 12], ["食蟻獸寶可夢", "將火焰當成舌頭來使用。會一點一點地熔化鐵蟻堅硬的外骨骼，然後把牠吃掉。", 14], ["鐵蟻寶可夢", "巨大的顎部能咬碎岩石。為了不讓沙螺蟒把蛋搶走，會和其他同類一起並肩戰鬥。", 3], ["粗魯寶可夢", "因為眼睛看不見，所以會又撞又咬，來判斷四周的狀況。", 8], ["粗暴寶可夢", "２個頭會爭搶同一個食物。明明沒有去和別人戰鬥，卻總是遍體鱗傷。", 14], ["凶暴寶可夢", "３個頭會輪流去咬敵人。在對方倒下之前，絕對不會停止攻擊。", 18], ["火炬寶可夢", "全身都相當溫暖。會從角的尖端噴出火來威嚇天敵或獵物。", 11], ["太陽寶可夢", "從熊熊燃燒著火焰的繭中誕生。在古代的壁畫上被描繪為火神。", 16], ["鐵心寶可夢", "生來就具有領導風範。即使是性情狂暴的寶可夢，在勾帕路翁面前也會變得溫順。", 21], ["岩窟寶可夢", "代拉基翁為保護寶可夢而與人類作戰的傳說在合眾地區廣為流傳。", 19], ["草原寶可夢", "以敏捷的身手像旋風一般將敵人玩弄於股掌之中，會用鋒利的角毫不留情地斬斷對手。", 20], ["旋風寶可夢", "可引發風暴的寶可夢。傳說由於它攪拌大氣，季節因此得以循環不息。據本人考察，近似人類的形態才是假象而非真身。（化身形態）此乃被稱為形態變化的現象。據考察，此一形同怪鳥的姿態才是其真正樣貌。曾被目擊以此姿態橫越大海。（靈獸形態）", 15, 1], ["雷擊寶可夢", "可引發風暴的寶可夢。傳說由於它攪拌大氣，季節因此得以循環不息。據本人考察，近似人類的形態才是假象而非真身。（化身形態）在閃電霹靂中現身。會自尾部的連串珠子降下雷擊掃蕩敵手。驚人的威力足以令敵手片甲不留。（靈獸形態）", 15, 1], ["白陽寶可夢", "在神話的敘述裡，如果人類蔑視真實、放縱欲望，牠就會用火焰燒盡他們的王國。", 32], ["黑陰寶可夢", "在神話的敘述裡，如果人類失去了正義之心，牠就會用狂暴的雷電毀滅他們的王國。", 29], ["豐饒寶可夢", "會在旋風與電擊的化身互相鬥爭之時現身並加以平息。在風暴與雷電過後，大地必將迎來豐收。（化身形態）以靈獸之姿翱翔天際時，會為大地帶來豐收，因而受到眾人崇敬。只需一刻光陰便能縱斷洗翠大地。（靈獸形態）", 15, 1], ["境界寶可夢", "為了穩定細胞組織，牠似乎用自己製造出的冷氣冰凍著身體。", 30], ["幼馬寶可夢", "據說當牠歷經艱難的戰鬥，藉此鍛鍊了額頭上的角之後，就能激發出自己真正的力量。", 14], ["旋律寶可夢", "用特殊的發聲法唱出的旋律可以自由地操縱聽者的情緒。（歌聲形態）美洛耶塔找回了被遺忘已久的歌，以魅惑的舞步令眾生為之傾倒。（舞步形態）", 6, 1], ["古生代寶可夢", "被某個組織復活的古生代的蟲寶可夢。背上的大炮被改造了。裝上填充了水能量的卡帶的樣子。會以飛行形態在空中飛翔。（水流卡帶）裝上填充了電能量的卡帶的樣子。會發射能量彈。（閃電卡帶）裝上填充了火能量的卡帶的樣子。擁有銳利的鋼爪。（火焰卡帶）裝上填充了冰能量的卡帶的樣子。毫無慈悲之心。（冰凍卡帶）", 15, 1], ["刺栗寶可夢", "若在頭錘快命中前注入力量，就能讓頭上的刺變得尖銳，並貫穿敵人的身體。", 4, 1], ["刺鎧寶可夢", "", 7], ["刺鎧寶可夢", "", 16], ["狐狸寶可夢", "擁有容易亢奮的性格。體溫也很容易變得過高，因此會利用耳朵放熱冷靜下來。", 4, 1], ["狐狸寶可夢", "會點燃尾巴上的樹枝並揮動它向夥伴傳遞信號。遇到危險時會轉動樹枝畫圈。", 10, 1], ["狐狸寶可夢", "會用木杖前端的火焰在地上留下燒焦的痕跡。以前的人會通過該痕跡的形狀來占卜。", 15, 1], ["泡蛙寶可夢", "看起來悠哉的樣子其實是用來欺騙敵人的演技。會冷不防地用迅雷不及掩耳的速度壓制敵人。", 3, 1], ["泡蛙寶可夢", "擅長活用地形的戰術。投擲被泡泡包著的小石頭時百發百中。", 6, 1], ["忍者寶可夢", "能通過卷在脖子上的長～舌頭所接觸到的空氣流動來察覺看不見身影的敵人的動靜。", 15, 1], ["挖洞寶可夢", "對危險很敏感。只要聽到鋼鎧鴉拍打翅膀的聲音，就會馬上挖洞鑽進地下藏身。", 4], ["挖洞寶可夢", "肚子上的體毛保溫性能優秀。在過去，人們會用牠掉落的毛來製作保暖服裝。", 10], ["知更鳥寶可夢", "一旦興奮體溫就會急速上升。赤手去摸牠有時甚至會被灼傷。", 3], ["火花寶可夢", "地盤意識很強，且性情好戰。火箭雀彼此之間也會為了爭奪覓食的地方而戰鬥。", 7], ["烈火寶可夢", "會以時速５００公里的速度進行突擊。對手連逃跑都來不及就被牠猛烈的腳踢給解決了。", 12], ["噴粉寶可夢", "吸入體內的毒素會變成黑色的粉末被排出體外，所以它可以吃毒葉和毒樹根。", 3, 1], ["噴粉寶可夢", "被毛頭小鷹的鳥嘴襲擊時，就會靠尖銳的體毛和帶毒的黑色粉末來迎戰。", 3, 1], ["鱗粉寶可夢", "身上的花紋會受到誕生地的氣候和風土影響而改變。這是它在極為寒冷的地方的樣子。（冰雪花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在降雪量多的地方能見到這種樣子。（雪國花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在氣候嚴寒的地方能見到這種樣子。（雪原花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在遼闊的地方能見到這種樣子。（大陸花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在綠意盎然的地方能見到這種樣子。（庭園花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在四季分明的地方能見到這種樣子。（高雅花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在花朵盛開的地方能見到這種樣子。（花園花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在日照強烈的地方能見到這種樣子。（摩登花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在海風吹拂的地方能見到這種樣子。（大海花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在島嶼群集的地方能見到這種樣子。（群島花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在少雨的地方能見到這種樣子。（荒野花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在極為乾旱的地方能見到這種樣子。（沙塵花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在大河流淌的地方能見到這種樣子。（大河花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在雨勢激烈的地方能見到這種樣子。（驟雨花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在熱帶氣候的地方能見到這種樣子。（熱帶草原花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在光線充足的地方能見到這種樣子。（太陽花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在四季如夏的地方能見到這種樣子。（大洋花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在熱帶雨林的地方能見到這種樣子。（熱帶雨林花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在神奇的地方能見到這種樣子。（幻彩花紋）身上的花紋會受到出生地的氣候和風土的影響而改變。在特別的地方能見到這種樣子。（球球花紋）", 12, 1], ["幼獅寶可夢", "血氣方剛且好奇心旺盛。當牠生氣或是開始戰鬥時，短短的鬃毛就會變熱。", 6], ["王者寶可夢", "能吐出攝氏６０００度的氣息，但不會用在獵物身上，因為牠比較喜歡吃生肉。", 15], ["單朵寶可夢", "頭上的冠是收集花粉製成的，蘊藏著治癒的效果。", 1], ["單朵寶可夢", "會把自己的力量分給花，用心地加以照料。絕不會原諒破壞花壇的傢伙。", 2], ["花園寶可夢", "擁有數百年的壽命。據說牠終其一生都會不斷守護著庭園。", 11], ["坐騎寶可夢", "直到最近為止都還有山嶽的居民乘坐在坐騎小羊的背上，在山路上移動。", 9, 1], ["坐騎寶可夢", "用角一碰就可以感受到對方的心情。從５０００年前起就一直協助著人類工作至今。", 17, 1], ["頑皮寶可夢", "為了不被小看而一直瞪著對手，然而繃緊的神經一旦稍有放鬆，牠就會在無意中露出笑臉。", 6], ["惡顏寶可夢", "透過葉子來洞悉敵人的動向。只要使出一記拳擊就能讓大型砂石車變成廢鐵。", 21], ["貴賓犬寶可夢", "如果放著不管，體毛就會不斷變長，但牠只允許信賴的人幫自己修剪。", 12], ["自制寶可夢", "雖然擁有可以彈飛職業摔角選手的精神力量，卻因無法好好控制而感到煩惱。", 3], ["抑制寶可夢", "雄性的防衛本能很強，在保護自己和夥伴時能發揮最大的威力。", 6], ["刀劍寶可夢", "獨劍鞘護手上的藍色眼珠是牠的本體。會用陳舊的布吸取人類的精氣。", 8], ["刀劍寶可夢", "２把劍會用令人眼花繚亂的速度不斷交替攻擊和防禦，藉以制服獵物。", 8], ["王劍寶可夢", "堅盾劍怪曾經用強大的靈力控制人和寶可夢，建立了適合自己生活的國家。", 17], ["香水寶可夢", "身上飄出的香氣能讓人們神魂顛倒。貴婦們對牠鍾愛萬分。", 2], ["芳香寶可夢", "會發出惡臭讓敵人喪失戰意，或者發出芳香的味道來幫助自己的夥伴。", 8], ["棉花糖寶可夢", "蓬鬆的體毛聞起來就像棉花糖一樣甜甜的。會放出黏答答的絲纏住敵人。", 4], ["泡沫奶油寶可夢", "因為體毛裡富含空氣，所以摸起來十分柔軟，重量也比看起來要輕。", 8], ["回轉寶可夢", "會讓敵人看到自己閃爍的發光體來讓對方喪失戰意，然後趁機逃之夭夭。", 4], ["倒轉寶可夢", "據說那些能夠改變歷史的重大事件其實都和烏賊王的催眠能力有關。", 15], ["雙手寶可夢", "如果２隻龜腳腳配合得不好，不但無法有效地攻擊和防禦，甚至沒辦法生存下去。", 5], ["集合寶可夢", "用手掌上的眼珠來觀察前後左右的狀況。遇上危機時手腳會自己動起來打倒對手。", 13], ["似草寶可夢", "看起來像是腐爛的海藻，因此會躲在海裡漂浮的藻屑裡混淆敵人的耳目。", 5], ["似草寶可夢", "透過讓頭頂類似帽子的部分浮出海面吸收陽光，就能夠製造龍之能量。", 18], ["水槍寶可夢", "右臂的鉗子能夠累積氣體，並且利用氣體爆炸噴射出像子彈般的水來打倒敵人。", 5], ["發射器寶可夢", "右臂是能夠發射海水砲彈的大砲。威力之強，甚至能夠擊沉油輪。", 13], ["發電寶可夢", "擁有太陽能發電的結構。如果有人打擾牠發電，牠就會因心理壓力而衰弱。", 5], ["發電寶可夢", "如果展開頸傘沐浴陽光，單憑１隻光電傘蜥就能製造出大城市所需的電力。", 10], ["幼君寶可夢", "任性且愛撒嬌。即使牠只是鬧著玩，也會讓訓練家受到重傷。", 8], ["暴君寶可夢", "只要牠的大顎一咬，就連汽車也會被粉碎。是古代世界的王者。", 25], ["凍原寶可夢", "已經滅絕的古代寶可夢。有時候還會以冰封狀態被發現喔。", 13], ["凍原寶可夢", "當牠大大地被激怒時，就會噴出猛烈的冰氣讓周圍一帶全被冰封。", 27], ["連結寶可夢", "伽勒爾地區的童話中有著美麗的仙子伊布擊退了可怕的龍寶可夢的故事。", 10], ["摔角寶可夢", "在使出致命的絕招之前一定要先擺出華麗的姿勢。有時也會在這一刻遭到反擊。", 8], ["天線寶可夢", "由於發電的能力不強，因此會從插座或其他的電氣寶可夢那裡偷電。", 2], ["寶石寶可夢", "據說在世界的某處，有個沉睡著許多小碎鑽的礦床，群體的女王也在那裡。", 3], ["軟體生物寶可夢", "牠的觸角是優秀的感覺器官。只要感覺到有敵人就會立刻躲起來，以此存活到了現在。", 3], ["軟體生物寶可夢", "背上的突起物裡裝著牠小小的腦子，裡面只想著吃飯和逃離敵人這兩件事。", 8], ["龍寶可夢", "用伸長角產生的力道來攻擊對手，產生的威力比重量級拳擊手的拳擊還強１００倍。", 20], ["鑰匙串寶可夢", "會用頭的前端吸取金屬離子。據說是因為愛鑰匙成癡，因此擬態成鑰匙的樣子。", 2], ["樹樁寶可夢", "用類似人類小孩的聲音鳴叫，把大人引到森林的深處，讓他們在其中迷失方向。", 4], ["老樹寶可夢", "腳尖伸出來的根鬚能連結森林中的樹木，並且自由自在地加以操縱。", 15], ["南瓜寶可夢", "南瓜的洞裡發出的光會催眠並控制看到牠的人和寶可夢。", 4], ["南瓜寶可夢", "南瓜怪人會在朔月的夜裡去別人家門口敲門。開了門的人會被牠帶往另一個世界。", 9], ["冰塊寶可夢", "棲息在極其寒冷的地域。會把自己的腳凍在冰岩怪的背上固定起來。", 10], ["冰山寶可夢", "雖然身體的裂縫會因白天的活動而變大，但只要一晚就能全部長好。", 20], ["音波寶可夢", "可以控制所有頻率的音波。就算是體型巨大的寶可夢，也對牠的超音波束手無策。", 5], ["音波寶可夢", "在黑暗中一邊飛行一邊發出能粉碎岩石的超音波痛擊敵人，然後用利齒給予致命的一擊。", 15], ["生命寶可夢", "據說，當頭上的角閃著七色光時，會分享永恆的生命。", 30, 1], ["破壞寶可夢", "聽說，壽命終結時，會吸光所有生物的生命，返回到繭的樣子。", 58, 1], ["秩序寶可夢", "據說當牠與威脅到生態系統的對手戰鬥時，會變化成更強大的樣子。", 50], ["寶石寶可夢", "小碎鑽的突變體。閃著粉紅色光輝的身體被贊為全世界最美。額頭上光輝奪目的鑽石竟然有２０００克拉重。別名皇家粉色公主。（超級進化）", 7, 1], ["頑童寶可夢", "會使用圓環把自己喜歡的東西收集到秘密的住所中。會鑽入環裡瞬間移動。\n（懲戒胡帕）將被封印的力量找回來後的本來面目。據說胸上的洞與異次元相連。（解放胡帕）", 5, 1], ["蒸汽寶可夢", "從背上的手臂裡噴射出體內的水蒸氣。有著把整座山一下子吹飛的威力。", 17, 1], ["草羽寶可夢", "白天利用光合作用積蓄力量，到了晚上則會悄無聲息地在空中飛翔，尋找獵物。", 3], ["刃羽寶可夢", "對整理翅膀絲毫不會怠慢。這不單是因為牠注重形象，也是為了讓刃羽保持銳利。", 7], ["箭羽寶可夢", "只要０.１秒就可以在翅膀的藤蔓上搭好箭羽、射向敵人，並在敵人發現前貫穿其要害。", 16], ["火貓寶可夢", "如果在得到火斑喵的信任前就想撫摸牠的話，要小心牠用尖銳的爪子抓你。", 4], ["火貓寶可夢", "如果敵人實力強勁，牠便會更有戰鬥的欲望，火焰鈴鐺的火力也會隨之上升。", 7], ["反派寶可夢", "雖然行為舉止十分粗野，卻也有著會去幫助弱小寶可夢的溫柔一面。", 18], ["海獅寶可夢", "每天拼命地練習，才終於能夠製造出又大又好用的氣球。", 4], ["偶像寶可夢", "到了風平浪靜的夜晚，會配合領隊西獅海壬的歌聲和夥伴們一起跳舞。", 6], ["獨唱者寶可夢", "對戰就是西獅海壬的舞台。牠那歌聲和舞動氣球的樣子使觀戰的人們為之傾倒。", 18], ["啄木鳥寶可夢", "看起來很細的脖子其實有著強韌的肌肉，能以每秒１６連擊的速度猛啄樹木。", 3], ["喇叭喙寶可夢", "會將吃掉的樹果種子從口中發射出去。散落在大地上的種子將孕育出新的草木。", 6], ["銃炮寶可夢", "以伴侶之間深厚的感情而聞名。被視為一種吉利的象徵，常被人帶到結婚典禮去。", 11], ["巡迴寶可夢", "雖然什麼都吃，但特別偏好活生生的新鮮食物，會為了尋找獵物而四處遊走。", 4], ["監視寶可夢", "忍耐力非常強，然而只要看見自己愛吃的小拉達，就會立刻忘我地撲上去。", 7], ["幼蟲寶可夢", "會用巨大的顎部在森林中挖地製造巢穴。最喜歡甜甜的樹汁。", 4], ["蓄電池寶可夢", "蟲電寶消化吃掉的落葉時會產生電能。牠會把這些電能儲存在自己肚子上的電囊中。", 5], ["鍬形蟲寶可夢", "如果牠在飛行時把蟲電寶抱住當作備用電池，就能連續發射電力超高的電磁光束。", 15], ["拳鬥寶可夢", "有時會錯把椰蛋樹當成椰子樹而爬上去。惹怒椰蛋樹的牠會被甩下來並遭到踩踏。", 6], ["毛蟹寶可夢", "習慣不經過大腦先動手打了再說。以前曾有過用連續不斷的拳擊把雪崩推回去的紀錄。", 17], ["舞蹈寶可夢", "吸食了朱紅色花蜜的花舞鳥。訓練家如果做出了錯誤的指示，感情起伏激烈的牠就會非常生氣。", 6], ["蜂虻寶可夢", "從敵人散發出的氣場來判斷對方下一步的行動。能輕盈地躲開攻擊並進行反擊。", 1], ["蜂虻寶可夢", "最討厭雨水弄濕自己。因為伽勒爾地區陰天居多，所以很難見得到牠的身影。", 2], ["小狗寶可夢", "會將脖子上的岩石射向地面來威嚇對手，趁對手畏縮的時候發起襲擊。", 5], ["狼寶可夢", "會用敏捷的動作將獵物一步步地逼入絕境。尖牙總是瞄準著對方的要害。", 8], ["小魚寶可夢", "感覺到危險時眼睛就會變得濕潤。眼淚的光亮會成為召集夥伴的信號，讓許多的弱丁魚聚在一起。", 2], ["非星寶可夢", "和阿羅拉的好壞星不同，伽勒爾的好壞星還沒發現到太陽珊瑚的枝有多好吃。", 4], ["非星寶可夢", "體內的毒囊中儲存著滿滿的劇毒，毒性強到能讓吼鯨王都痛苦三天三夜。", 7], ["驢寶可夢", "在把自己吃土製造出的泥巴塗在腳上之後，無論走在路況多麼差的路上都不會打滑。", 10], ["挽馬寶可夢", "擁有很強的耐力，可以不眠不休地拉著１０噸重的貨物縱貫伽勒爾地區。", 25], ["水泡寶可夢", "平時生活在水中，也會戴上水泡去陸地上尋找食物。", 3], ["水泡寶可夢", "把滴蛛放進頭上的水泡裡，一邊餵牠吃剩的食物，一邊照顧牠。", 18], ["鐮草寶可夢", "白天時會沐浴著陽光酣酣睡覺。到了半夜才會醒來活動。", 3], ["花鐮寶可夢", "雙臂上的花瓣既輕薄又鋒利。而且還能夠收集光線來射出光束。", 9], ["發光寶可夢", "白天也生活在昏暗的森林裡。會一邊閃爍一邊散播發著光的孢子來讓敵人陷入沉睡。", 2], ["發光寶可夢", "如果半夜裡在森林的深處看見光亮，記住千萬不要接近。燈罩夜菇會讓你睡著的。", 10], ["毒蜥寶可夢", "悄悄地從背後靠近獵物，在對方察覺之前釋放毒氣，讓對方動彈不得。", 6], ["毒蜥寶可夢", "據說焰后蜥之間在爭鬥時，是透過比拼誰帶著更多隻雄性夜盜火蜥來定勝負的。", 12], ["抓狂寶可夢", "為了保護自己的身體而胡亂揮舞前腳的樣子雖然可愛，威力卻大到能將大樹折斷。", 5], ["強臂寶可夢", "會用令格鬥家都無地自容的技術把逮住的獵物夾在腋下，帶回自己的住處。", 21], ["水果寶可夢", "受到襲擊時流下的汗水非常甜美可口。那種香氣會吸引更多敵人的注意。", 3], ["水果寶可夢", "會用頭部的果蒂擊打飛來啄食自己的藍鴉，並且對牠使出猛烈的踢擊。", 7], ["水果寶可夢", "用又尖又硬的腳尖施展踢擊，朝對手的身體和心靈留下無法磨滅的創傷。", 12], ["摘花寶可夢", "飄散著迷人香氣的寶可夢。由於黏在身上的花朵不一樣，每隻花療環環的香味也都不同。", 1], ["賢者寶可夢", "對森林的各個角落都瞭若指掌。如果有寶可夢受傷了，就會去尋找藥草為牠們治療。", 15], ["配合寶可夢", "２０幾隻形成團隊來生活。靠著每個成員明確的分工，在嚴苛的大自然中生存下來。", 20], ["疾行寶可夢", "成群聚集，隨時保持警惕。只要察覺到有敵人，就會分散開來四處逃竄。", 5], ["裝甲寶可夢", "生活在海底的洞窟或沉船裡。會去和八爪武師決戰，輸掉的一方便會成為對方的食物。", 20], ["沙丘寶可夢", "主要棲息在沙灘上。會操縱把手伸進自己嘴巴裡的對手，藉此讓自己的身體變得更大。", 5], ["沙堡寶可夢", "雖然住在海灘上，但很討厭水。要是被激烈的大雨淋到，就沒辦法維持城堡的形狀。", 13], ["海參寶可夢", "覆蓋著皮膚的黏液具有出眾的保濕效果，即使在陸地上待好幾天也不會乾掉。", 3], ["人工寶可夢", "以神話中的寶可夢為原型所創造出的寶可夢，被戴上了抑制力量失控的面罩。", 19], ["人工寶可夢", "與所信賴的訓練家之間的牽絆是解放牠真正力量的最後一個要素。", 23], ["流星寶可夢", "外殼非常堅固，但墜落到地上時的衝擊會讓牠碎成細屑。", 3], ["半夢半醒寶可夢", "終其一生都處於睡著的狀態。這是因為牠所吃的葉子裡含有類似麻醉藥的成分。", 4], ["爆炸龜寶可夢", "在火山上生活，吃下的硫磺就是甲殼上炸藥的原料。連糞便也會爆炸，十分危險。", 20], ["蜷縮寶可夢", "在危急時刻會把身體捲成一團、倒豎起背上的尖刺，不分青紅皂白地發出電擊。", 3], ["畫皮寶可夢", "有一位學者為了研究而看了牠的破布裡面，結果患上怪病而離開人世。", 2], ["磨牙寶可夢", "厚實的皮膚連好壞星的針也無法穿透。會用結實的牙齒把針咬碎之後吃下去。", 9], ["悠遊寶可夢", "心地善良愛親近人，但只要生氣就會颳起強風吹倒一切。", 30], ["碎藻寶可夢", "把錨拋到海裡，伏擊獵物。會去捕捉巨大的吼鯨王，吸取牠們的精氣。", 39], ["鱗片寶可夢", "體毛變成了像金屬一般堅硬的鱗片。透過敲響鱗片來和夥伴溝通。", 6], ["鱗片寶可夢", "敲響鱗片、發出吼聲，接著向對手發起挑戰，並用鋒利的爪子撕裂對手。", 12], ["鱗片寶可夢", "遺跡壁畫中古代戰士身上穿著的盔甲是用杖尾鱗甲龍的鱗片製成的。", 16], ["土地神寶可夢", "操縱雷電，是美樂美樂的守護神。有著旺盛的好奇心，會不時在人們面前現身。", 18], ["土地神寶可夢", "被稱為守護神，卻同時有著天真無邪與殘酷的性格，可說是大自然的化身。", 12], ["土地神寶可夢", "會搖響尾巴告知周圍自己的位置，藉此避免不必要的鬥爭。是操縱草木的烏拉烏拉守護神。", 19], ["土地神寶可夢", "被稱為守護神，但有時會對隨便靠近自己的對手帶來恐怖的災難。", 13], ["星雲寶可夢", "沒有警戒心且好奇心強，所以經常會遇到麻煩。危急時會用瞬間移動來逃跑。", 2], ["原始星寶可夢", "以驚人的氣勢吸入大氣中的塵埃，努力用內核製造著進化的能源。", 1], ["日輪寶可夢", "曾經被稱為吞食太陽之獸。能釋放出無盡的光能。", 34], ["月輪寶可夢", "奪走四周所有的光，自己則變身為滿月的模樣，在黑夜中散發出光芒。", 40], ["寄生寶可夢", "從究極之洞中現身來到這個世界。似乎會靠寄生在寶可夢或人類身上來生存。", 12], ["膨脹寶可夢", "會向對手炫耀自己膨脹到異常程度的肌肉。是究極異獸的一種。", 24], ["美艷寶可夢", "在這個世界是危險的異類，但牠在原本棲息的世界裡似乎是隨處可見的普通生物。", 18], ["燈飾寶可夢", "被稱為究極異獸。也有一些會像樹木一樣，把手腳刺進地面動也不動。", 38], ["發射寶可夢", "在這個世界是危險的異類，但牠在原本棲息的世界裡似乎是隨處可見的普通生物。", 92], ["拔刀寶可夢", "在這個世界是危險的異類，但牠在原本棲息的世界裡似乎是隨處可見的普通生物。", 3], ["異食寶可夢", "被稱為究極異獸的未知生命。不知是否總覺得肚子餓，牠隨時都在吃東西。", 55], ["稜鏡寶可夢", "為生存而發狂般地尋找著光。會發射出雷射光，將所有東西切成碎片。", 24], ["人造寶可夢", "由大約５００年前的科學家所製造。本體是被稱為魂心的零件。", 10], ["棲影寶可夢", "擁有潛入一切影子裡的能力，所以在很長一段時間裡都沒有任何人發現牠。", 7], ["毒針寶可夢", "棲息在異世界的究極異獸。會從頭上的毒針朝對手噴出毒液，然後放聲大笑。", 6], ["毒針寶可夢", "究極異獸的一種。會從毒針發射出黏度很高的發光毒液。", 36], ["石牆寶可夢", "疑似究極異獸的神秘生命體。突然動起來展開襲擊的石牆，它的真面目就是這個傢伙。", 55], ["煙火寶可夢", "從究極之洞中出現的究極異獸。會用爆炸嚇唬對手，然後趁機奪取對方的精氣。", 18], ["奔雷寶可夢", "從手腳的肉球放電。當捷拉奧拉奔馳而過時，周圍將充斥著電閃雷鳴。", 15], ["螺帽寶可夢", "美錄坦們雖然聚在一起生活，但當時機到來，會由最強的那１隻吸收其他的夥伴來進化。", 2], ["螺帽寶可夢", "美錄梅塔利用離心力帶動沉重的螺帽揮出的拳擊被認為是寶可夢界之最。", 25], ["小猴寶可夢", "會用木棒連續擊打來攻擊。在以飛快的速度擊打的同時，情緒也會變得越來越高漲。", 3], ["節拍寶可夢", "打著激烈的節拍戰鬥時，由於過於忘我，甚至不會意識到自己已經把對手打昏了。", 7], ["鼓手寶可夢", "打鼓技巧最高超的那一隻會成為首領。性情溫和，重視族群的和諧相處。", 21], ["兔子寶可夢", "一旦做好了戰鬥的準備，牠鼻頭上和腳底的肉球就會散發出極度的高溫。", 3], ["兔子寶可夢", "會用腳把樹果從樹木上踢落，用來練習挑球，藉此鍛鍊自己的腳法。", 6], ["前鋒寶可夢", "擁有熟練的進攻和防守技巧。只要得到聲援就會更有衝勁，但有時會為了出風頭而弄巧成拙。", 14], ["水蜥寶可夢", "皮膚在濕掉時會變色，彷彿像是隱身了一樣，誰都看不見牠的身影。", 3], ["水蜥寶可夢", "頭腦聰明但是很怕麻煩。為了不讓敵人接近自己的地盤，在各個地方都設下了陷阱。", 7], ["特工寶可夢", "能從指尖射出速度高達３馬赫的水槍。牠的瞬膜能幫助牠看穿敵人的弱點，準確地擊中要害。", 19], ["貪吃寶可夢", "由於牠無論何時都在吃樹果，使得牠比外表看起來還要頑強。會出現在田地裡尋找樹果。", 3], ["貪慾寶可夢", "無論多麼堅硬的樹果殼都能用引以為傲的大牙咬碎。在伽勒爾是很常見的寶可夢。", 6], ["小鳥寶可夢", "嬌小的體型讓牠能敏捷地飛翔。攻其不備的戰法將體型巨大的對手玩弄於股掌之間。", 2], ["烏鴉寶可夢", "歷經無數次艱難的戰鬥後，牠學會了該如何正確地判斷敵人的力量。", 8], ["烏鴉寶可夢", "擁有優秀飛行能力和極度聰明頭腦的牠在伽勒爾地區從事飛翔計程車的工作。", 22], ["幼蟲寶可夢", "經常出現在田地裡的寶可夢。會透過長在身體上的毛來感應周圍發生的事。", 4], ["天線罩寶可夢", "正在殼裡成長著。用精神力量掌握外界的狀況，做好進化的準備。", 4], ["七星寶可夢", "釋放出精神力量來調查周圍的情況。牠的偵測範圍甚至可以達到方圓１０公里。", 4], ["狐狸寶可夢", "性情謹慎且狡猾。在偷盜食物逃走的時候會用尾巴擦掉自己的足跡。", 6], ["狐狸寶可夢", "靠著輕盈的身體和銳利的爪子到處去偷食物和蛋。逐電犬是牠的天敵。", 12], ["花飾寶可夢", "會隨著微風一邊轉圈圈一邊愉快地唱歌。許多人因為喜歡這可愛的模樣而培育牠。", 4], ["棉飾寶可夢", "用牠頭上的棉絮製成的線有著十分美麗動人的光澤，是伽勒爾地區的名產。", 5], ["綿羊寶可夢", "要是身上的毛長得太長就會不能動彈。用毛辮羊的體毛織成的布結實得讓人吃驚。", 6], ["綿羊寶可夢", "長得長長的角是為了向異性求愛而存在的。牠從不會把角當作武器。", 13], ["咬住寶可夢", "會用頭上硬如岩石的角攻擊敵人。趁其不備之時大口咬住對方，一旦咬住便再也不會鬆口。", 3], ["緊咬寶可夢", "頸部可以伸縮。能從遠處迅速伸長頸部，用銳利的牙齒解決對手。", 10], ["小狗寶可夢", "因為想要得到零食而幫助人類工作的貪吃鬼。總是帶著電火花跑來跑去。", 3], ["狗寶可夢", "電力增強了牠的腳力。當以最高速度奔跑時，時速可以輕易超過９０公里。", 10], ["煤炭寶可夢", "在滿是岩石的崎嶇路面上也能像獨輪車那樣自在移動。靠燃燒煤炭維持生命。", 3], ["煤炭寶可夢", "能透過高速旋轉自己的腳，以３０公里的時速奔跑。能噴出攝氏１０００度的火焰。", 11], ["煤炭寶可夢", "進入戰鬥狀態後，牠會把煤炭山燃燒得通紅，飛撒火花來燒焦四周。", 28], ["蘋果居寶可夢", "一出生就躲進了蘋果中，一邊吃果肉一邊成長。進化方向依蘋果的味道而定。", 2], ["蘋果翅寶可夢", "會用蘋果皮的翅膀飛翔，並吐出強酸性的唾液。能變成蘋果的形狀。", 3], ["蘋果汁寶可夢", "身體被甜甜的蜜汁包裹，背部的皮尤其甘甜，過去曾經是小孩的零食。", 4], ["沙蛇寶可夢", "會從鼻孔噴射出沙子，趁敵人看不清的時候躲進地底下藏身。", 22], ["沙蛇寶可夢", "牠之所以會以獨特的方式盤繞自己的身體，是為了能更有效率地噴射沙囊中的沙子。", 38], ["一口吞寶可夢", "非常貪吃，會把刺梭魚整隻吞進嘴裡。偶爾也會搞錯對象去咬其他的寶可夢。", 8], ["突擊寶可夢", "吃飽了之後動作會變得極度遲緩，於是就被古月鳥整隻吞了下去。", 5], ["穿刺寶可夢", "會旋轉著自己的尾鰭一口氣突擊。能夠以超過１００節的速度貫穿獵物。", 13], ["嬰兒寶可夢", "透過讓自身的毒素產生化學反應來發電。電力雖然弱，卻能造成麻痺。", 4], ["龐克寶可夢", "氣勢洶洶的急性子。會大口喝下混濁的水，吸收其中所含的毒素。", 16], ["發熱寶可夢", "會用滾燙的身體勒緊獵物，等到烤得恰到好處之時，就把牠們大口大口地吃掉。", 7], ["發熱寶可夢", "性情極具攻擊性。危險的不只是牠燒燙的身體，大大的獠牙也銳利無比。", 30], ["纏人寶可夢", "智商大致相當於３歲的兒童。雖然觸手經常斷掉，但因為能再生，所以牠並不在意。", 6], ["柔術寶可夢", "會為了試自己的身手而登上陸地尋找對手。戰鬥結束後就會回到海裡。", 16], ["紅茶寶可夢", "被牠當成住處的茶杯是有名的古董餐具。市面上有很多贗品。", 1], ["紅茶寶可夢", "每當發現喝剩的紅茶，牠就會把自己的身體倒進去，讓那壺紅茶變成怖思壺。", 2], ["寧靜寶可夢", "喜歡沒有人煙的地方。一旦感覺到強烈的情感，就會一溜煙地逃走。", 4], ["肅靜寶可夢", "會用頭上的辮子攻擊對手，讓對方安靜下來。破壞力強到能一擊ＫＯ職業拳擊手。", 6], ["寂靜寶可夢", "又被稱為森林魔女。如果有人大吵大鬧，可能會被牠用觸手上的爪子撕碎。", 21], ["捉弄寶可夢", "不但會溜進民宅偷盜，還會吸收人們悔恨時的負面能量。", 4], ["壞心眼寶可夢", "喜歡動歪腦筋，把人們引誘到深夜的森林中。似乎擁有培育農作物的能力。", 8], ["健美寶可夢", "毛髮能發揮肌肉纖維般的作用。伸展開來時會像觸手那樣把對手纏繞起來。", 15], ["停止寶可夢", "在不斷的鬥爭中得到了進化。牠交叉著雙臂發出的怒吼能讓一切對手都為之膽怯。", 16], ["維京寶可夢", "在日復一日的戰鬥中得以進化。進化的結果是那危險的指甲，留長後能當作短劍來用。", 8], ["珊瑚寶可夢", "一定要小心牠那包覆著靈魂的靈體。如果觸摸到，就會像石頭一樣動彈不得。", 10], ["黃嘴鴨寶可夢", "會用堅硬的蔥葉抵擋攻擊，接著用鋒利的莖反擊。牠的蔥既是武器也是食材。", 8], ["喜劇演員寶可夢", "幽默的動作使牠獲得了眾人的喜愛。能從腹部的圖案釋放出精神力量。", 15], ["怨念寶可夢", "絕對不能觸摸牠影子般的身體，否則牠會讓你看到印刻在牠畫中的恐怖記憶。", 16], ["鮮奶油寶可夢", "據說有小仙奶現身的蛋糕店保證能生意興隆。", 2], ["鮮奶油寶可夢", "當牠感到幸福的時候，手中產生出的鮮奶油會變得更加香濃甜美。", 3], ["陣形寶可夢", "６隻為一體的寶可夢。慣於團隊行動，會一邊變換陣形一邊戰鬥。", 30], ["海膽寶可夢", "每根刺裡都儲存著電力。即使是折斷的刺也至少能持續放電３小時。", 3], ["蟲寶寶寶可夢", "會吃地面上的積雪。吃得越多，背上的刺就會長得越挺拔。", 3], ["冰蛾寶可夢", "絕不放過破壞山野環境的人。會用冰冷的翅膀四處飛翔，製造出暴風雪來懲罰他們。", 13], ["巨石寶可夢", "每年會有一天，牠們會在特定的時間突然出現，聚集在一起排成一個圈。", 25], ["企鵝寶可夢", "無論何時都用冰塊冰鎮著自己怕熱的臉。會把頭頂上的毛垂到海裡釣食物吃。", 14], ["感情寶可夢", "能透過自己的角去感受附近生物的情感。正面情緒是牠的能量之源。", 9], ["雙面寶可夢", "無論怎麼吃都會馬上肚子餓。十分珍愛自己用電烘烤過的種子，隨時都帶在身上。", 3], ["像銅寶可夢", "擅長需要力氣的工作。銅質的身體會因雨水而生鏽，轉變成鮮豔的綠色。", 12], ["像銅寶可夢", "群居的寶可夢。鼻子的握力十分強勁，甚至能把大石頭弄得粉碎。", 30], ["化石寶可夢", "會用尾部結實的肌肉發電。與下半身相比，上半身真的太小了。", 18], ["化石寶可夢", "曾經生活在古代的海邊，能用身體的冰來保存食物，但由於動作太遲緩而滅絕了。", 23], ["化石寶可夢", "雖然能用自豪的腳力以６０公里的時速奔跑，但是只能在水中呼吸。", 23], ["化石寶可夢", "面部的皮膚無論受到什麼攻擊都不會受傷，但由於呼吸起來不方便而滅絕了。", 20], ["合金寶可夢", "由特殊金屬構成的身體十分輕盈，能夠靈活地活動。不喜歡下雨，所以住在洞窟裡。", 18], ["哀怨寶可夢", "雖然單獨１隻弱得甚至敵不過小孩，但會和夥伴合作一起鍛鍊，透過進化而變得更強。", 5], ["保姆寶可夢", "要是沒讓自己在照顧的多龍梅西亞乘在頭上就靜不下心來，甚至會因此試圖把別的寶可夢放到頭上。", 14], ["隱形寶可夢", "牠角裡的多龍梅西亞似乎滿心期待著能被以音速發射出去。", 30], ["強者寶可夢", "這隻寶可夢被認為是沉睡已久的藏瑪然特的姐姐，也有人認為牠們之間是勁敵關係。", 28], ["強者寶可夢", "以石像般的姿態陷入長久沉眠的寶可夢。幾乎就要被人們所遺忘。", 29], ["超極巨寶可夢", "來自於２萬年前墜落到地上的隕石之中。似乎與極巨化之謎有所關聯。", 200], ["拳法寶可夢", "拉緊頭上又白又長的體毛就會變得氣勢高昂，並且由丹田湧出力量。", 6], ["拳法寶可夢", "棲息在遙遠地區的山岳地帶。會在斷崖絕壁上來回奔跑鍛鍊下盤，磨練招式。", 19], ["惡猿寶可夢", "生長在身上的藤蔓斷落後會化為土壤的養分，孕育森林裡的各種植物。", 18], ["電子寶可夢", "全身都是能發電的器官。牠製造的電能可以滿足伽勒爾全域的電力需求。", 12], ["龍玉寶可夢", "全身是由龍之能量的結晶打造而成。據說牠擁有所有的龍寶可夢的力量。", 21], ["烈馬寶可夢", "擁有十分驚人的怪力。遮住臉部的冰面罩比鑽石還要堅硬１００倍。", 22], ["駿馬寶可夢", "在漆黑的夜裡奔馳，吸取正在睡覺的生物的生命能量。喜愛孤獨與寂靜。", 20], ["國王寶可夢", "曾在很久以前統治伽勒爾的傳說之王。擁有治癒心靈，讓草木發芽的力量。", 11], ["大角寶可夢", "製造肉眼不可見的障壁時，黑珠會發出妖異的光輝。從它身上脫落的鬍鬚是用來製作溫暖冬衣的實用原料。", 18, 1], ["斧鉞寶可夢", "在火山地帶能以極低概率發現的礦石讓它實現了部分身體變為岩石的進化。", 18, 1], ["泥炭寶可夢", "在飄洋過海所到達的土地上存活下來的結果，讓它的樣子和能力起了特別的變化。（赫月）", 24, 1], ["大魚寶可夢", "在前往出生的河川的艱苦旅程中喪命的夥伴的靈魂時刻纏繞在它的身上。（雄性的樣子）纏繞在身上的夥伴們的靈魂化為了推進力，能若無其事地在激流中游泳。（雌性的樣子）", 30, 1], ["攀崖寶可夢", "擁有凌駕其他物種之上的身體能力以及劇毒。在寒冷的高地上所向無敵。偏好獨自行動，而不會集結成群。", 13, 1], ["劍山寶可夢", "即使在睡著的時候，只要有會動的東西接近，毒針就會無意識地作出反應刺過去。", 25, 1], ["愛憎寶可夢", "當它越過大海飛來，便代表嚴寒的冬季即將終結。傳說中其慈愛將使新的生命在洗翠大地上萌芽。（化身形態）自女人的姿態變化而成。若有誰做出糟蹋生命之事，便會從雲海中現身，憤怒地降下無情的懲罰。（靈獸形態）", 16, 1], ["鼠寶可夢", "長著２顆大牙，碰到什麼都會先咬上一口。只要看見１隻出沒，附近肯定還住著40隻以上。", 3], ["鼠寶可夢", "為了取得水中的食物，牠會利用後腳上的小蹼在河裡游泳。", 7], ["鼠寶可夢", "如果電囊空了，牠就會直直地豎起尾巴，收集空氣中的電流。", 7], ["鼠寶可夢", "會在地面挖洞築巢。即使遇到地下堅硬的岩石，也會用銳利的爪子擊碎並向前挖進。", 7], ["鼠寶可夢", "會用銳利的爪子當作鉤子來爬樹。這是為了將樹果擊落，分給在樹下等待的穿山鼠們。", 12], ["狐狸寶可夢", "隨著身體的成長，６根尾巴的毛髮也會變得更漂亮。緊緊抱著牠時能感到微微的溫暖。", 6], ["狐狸寶可夢", "聰明伶俐但很會記仇。據說如果敢亂抓牠的尾巴，牠就會纏著你作祟１０００年。", 11], ["鼴鼠寶可夢", "在地下較淺的地方移動。被牠挖掘過的地面會鼓起來，所以非常容易發現。", 2], ["鼴鼠寶可夢", "三胞胎的地鼠，擁有能夠挖掘到地下１００公里深的潛力。沒人知道牠在地下的部分究竟長成什麼樣子。", 7], ["妖怪貓寶可夢", "為了不弄髒額頭上的金幣，會常常洗臉。和伽勒爾的喵喵關係不好。", 4], ["暹羅貓寶可夢", "擁有優雅高貴的身姿。與野蠻的喵頭目個性不合，互相看不起對方。", 11], ["岩石寶可夢", "大量棲息在山路之類的地方。不小心踩到牠會讓牠生氣，所以走路的時候要小心。", 4], ["岩石寶可夢", "經常在山路上滾動。滾動時從不會去理會前面的路上有什麼東西。", 10], ["重量級寶可夢", "剛蛻皮的時候身體比較軟而且顏色偏白，但在接觸到空氣後很快就會變硬。", 17], ["污泥寶可夢", "由許多污泥凝聚而成。散發著惡臭，讓人無法觸碰。經過的地方寸草不生。", 7], ["污泥寶可夢", "奇臭無比！雖然臭到令人昏倒，但臭臭泥的鼻子已經退化，所以牠自己聞不到味道。", 10], ["椰子寶可夢", "３顆頭團結一致發出的精神力量威力強大。天氣變陰時動作就會變得遲緩。", 109], ["愛骨寶可夢", "進化時，原本戴在頭上的母親頭骨化為了牠身體的一部份。不但如此，性格也變得很凶暴。", 10], ["妖怪貓寶可夢", "為了不弄髒額頭上的金幣，會常常洗臉。和伽勒爾的喵喵關係不好。", 4], ["火馬寶可夢", "得到了小火馬認可的人，在觸摸牠燃燒著的鬃毛時不會覺得燙手，真是不可思議。", 8], ["火馬寶可夢", "奔跑速度最快的烈焰馬會成為首領，決定族群前往的地點和奔跑速度。", 17], ["憨憨寶可夢", "尾巴浸在水裡時會滲出甜味，牠會以此當誘餌來吸引並且釣起寶可夢。", 12], ["寄居蟹寶可夢", "被大舌貝狠狠咬下的衝擊讓牠變得能用兩腳行走。如果大舌貝脫落了，牠似乎就會變回呆呆獸。", 16], ["王者寶可夢", "只要開口提問，任何難題牠都會幫忙解開，但是無人能夠理解呆呆王的語言。", 18], ["黃嘴鴨寶可夢", "用植物的莖來戰鬥。莖的揮舞方式存在著好幾種不同的流派。", 8], ["毒氣寶可夢", "雖然吸入空氣的力量稍弱於伽勒爾的雙彈瓦斯，製造出的毒素卻更加強力。", 30], ["屏障寶可夢", "擅長表演默劇。用手指放出的波動製造牆壁，保護自己免於大多數的攻擊。", 14], ["冰凍寶可夢", "擁有能自在操縱冰的能力。據說是棲息在永凍之地的雪山中。", 17], ["電擊寶可夢", "傳說的鳥寶可夢。據說只要牠磨蹭翅膀，立刻就會有雷電劈下。", 16], ["火焰寶可夢", "相傳牠會以美麗燃燒的翅膀照亮山路，救助在山中遇險的人。", 20], ["珊瑚寶可夢", "在溫暖的大海裡生活。也曾經大量棲息於上古時期的伽勒爾近海。", 6], ["豆貍寶可夢", "伽勒爾的蛇紋熊適應了其他地區環境後的樣子。十分擅長找東西。", 4], ["猛衝寶可夢", "用自己超群的爆發力和銳利的爪子來制服獵物。不擅長在彎曲的道路上奔跑。", 5], ["不倒翁寶可夢", "在牠睡覺的時候，無論是推是拉，牠都不會倒下。因為象徵著吉利而大受歡迎。", 7], ["爆燃寶可夢", "體內的火焰燃得越旺，力量就越大。火焰的溫度有時甚至能超過１４００度。", 17], ["魂寶可夢", "古代人的靈魂變成了寶可夢。為了尋找認得自己長相的人而在遺跡裡徘徊。", 5], ["陷阱寶可夢", "當從身上的黃色斑紋裡釋放出強大電流時，牠會莫名地露出微笑。", 7], ["小狗寶可夢", "性格忠誠。為了保護自己的訓練家，會拼命地朝對手狂吠。", 8], ["傳說寶可夢", "從古時候起就是擄獲眾多人心的美麗寶可夢。能像飛一樣輕盈地奔跑。", 20], ["球寶可夢", "據說和精靈球相似的外型是牠的保護色，但令人意外地牠其實很容易就會自爆。", 5], ["球寶可夢", "只要受到任何一點衝擊，體內的電能就會迅速膨脹然後爆炸。", 12], ["火山寶可夢", "該寶可夢藏有大絕招。會摩擦熊熊燃燒著的體毛，掀起爆炸氣浪進行攻擊。", 16, 1], ["氣球寶可夢", "全身上下的小針是由鱗片變化而來的。如果被刺中的話，就會中毒並陷入昏迷。", 5], ["鉤爪寶可夢", "性格狡猾且凶猛。會趁著雙親不在時侵入巢穴把蛋盜走。", 9], ["威嚴寶可夢", "拔刀術的高手。會用收在前腿鎧甲裡的大刀一劍定勝負。", 15, 1], ["花飾寶可夢", "由牠的花朵提煉的精油有著極致的香氣，但價格同時也是貴得令人眼睛幾乎要掉出來。", 12], ["惡狐寶可夢", "為了尋找食物，有時還會幻化成人類出現在城鎮裡。通常都會變成小孩子。", 7], ["妖狐寶可夢", "孤獨的訓練家會命令索羅亞克讓他看見幻影，藉此紓解一個人的寂寞。", 16], ["勇猛寶可夢", "性情粗暴、血氣方剛，因此被鋼鎧鴉奪走了伽勒爾運送員的地位。", 17], ["軟體生物寶可夢", "背上的突起物裡裝著牠小小的腦子，裡面只想著吃飯和逃離敵人這兩件事。", 7], ["龍寶可夢", "用伸長角產生的力道來攻擊對手，產生的威力比重量級拳擊手的拳擊還強１００倍。", 17], ["冰山寶可夢", "雖然身體的裂縫會因白天的活動而變大，但只要一晚就能全部長好。", 14], ["箭羽寶可夢", "只要０.１秒就可以在翅膀的藤蔓上搭好箭羽、射向敵人，並在敵人發現前貫穿其要害。", 16], ["暴牛寶可夢", "棲息在伽勒爾的肯泰羅性格暴躁，絕不會允許人類騎到自己的背上。", 14], ["暴牛寶可夢", "棲息在伽勒爾的肯泰羅性格暴躁，絕不會允許人類騎到自己的背上。", 14], ["暴牛寶可夢", "棲息在伽勒爾的肯泰羅性格暴躁，絕不會允許人類騎到自己的背上。", 14], ["水魚寶可夢", "為了在地面上行走時不讓皮膚乾燥，會用有毒的黏膜覆蓋身體。", 4], ["草貓寶可夢", "毛茸茸的體毛有著近似於植物的成分。會勤於洗臉以防止乾燥。", 4, 1], ["草貓寶可夢", "靈巧地操控長長的體毛下隱藏著的藤蔓，接著把堅硬的花苞甩向敵人。", 9, 1], ["魔術師寶可夢", "花看似浮在空中，其實它是通過斗篷內的毛的反射來隱藏住了莖。", 15, 1], ["火鱷寶可夢", "會躺在溫暖的岩石上，利用四邊形的鱗片吸收的熱量來製造火之能量。", 4, 1], ["火鱷寶可夢", "由於火之能量與過剩的生命力相互結合，使它頭上出現了蛋狀的火球。", 10, 1], ["歌手寶可夢", "能以歌聲改變外形的火鳥，據說是由靈魂寄宿在頭上的火球所形成的。", 16, 1], ["小鴨寶可夢", "很久以前從遠方的土地來到這裡棲息。羽毛分泌出的凝膠有防水和防汙的效果。", 5, 1], ["習藝寶可夢", "通過在淺灘持續奔跑來鍛鍊腰腿，藉此與夥伴比拼誰的腿技更為華麗。", 12, 1], ["舞者寶可夢", "活用只要一腳就能踢翻卡車的強韌腳力，展現充滿異國風情的舞蹈。", 18, 1], ["豬寶可夢", "一整天都在覓食。明明擁有優秀的嗅覺，卻只用來尋找食物。", 5, 1], ["豬寶可夢", "以自己細緻透亮的肌膚為傲。會從尾巴的前端釋放出凝縮的香氣。（雄性的樣子）會釋放出如花般的香氣。肌肉發達的腿可以輕而易舉地跳過５米高。（雌性的樣子）", 10, 1], ["線球寶可夢", "包裹著身體的絲線團具有十足的彈力，能把天敵飛天螳螂的鐮刀反彈回去。", 3, 1], ["陷阱寶可夢", "用絲線吸附在樹枝或天花板上無聲無息地行動。會在自己被發現之前將獵物打倒。", 10, 1], ["蝗蟲寶可夢", "總是將第３雙腳折起來。擁有陷入危機時能夠跳躍１０米以上的腳力。", 2, 1], ["蝗蟲寶可夢", "認真起來時會靠折起的腳站起來進入決戰模式。會在短時間內壓制敵人。", 10, 1], ["鼠寶可夢", "臉頰上的電囊尚未發達。必須拼命摩擦前腳的肉球才得以製造出電力。", 3, 1], ["鼠寶可夢", "當群體受到襲擊的時候，會率先挑起戰鬥，並活用電擊的格鬥招式打倒敵人。", 4, 1], ["押掌寶可夢", "雖然平時動作慢吞吞的，但在不得不面對戰鬥時，會以迅雷不及掩耳的身手擊潰敵人。", 9, 1], ["成對寶可夢", "憑藉默契十足的團隊合作，用門牙切斷能當作巢穴的材料的東西，並將其搬走。", 3, 1], ["家族寶可夢", "會製造巨大的巢穴，並根據用途來分出多個房間，包含寢室、餐廳等等。（三隻家庭）不知不覺之間多了２只小孩。它們看起來像是一家子，但真相如何沒人知道。（四隻家庭）", 3, 1], ["小狗寶可夢", "摸起來既溼潤又光滑。吐息中包含的酵母可以讓周圍的東西發酵。", 3, 1], ["狗寶可夢", "身體散發出的迷人香氣有助於小麥的成長，因此在農村一直備受重視。", 5, 1], ["橄欖寶可夢", "從頭上的果實噴出油，以此保護自己不受敵人攻擊。那種油苦澀到能讓人跳起來。", 3, 1], ["橄欖寶可夢", "樂於分享自己香氣新鮮又美味可口的油。自古以來直至今日都與人類共存。", 6, 1], ["橄欖寶可夢", "性情溫和，慈悲為懷。會把營養豐富且美味可口的油分享給虛弱的寶可夢。", 14, 1], ["鸚鵡寶可夢", "喜歡棲息在街道上。會以羽毛的顏色來組隊，然後展開領地之爭。（綠羽毛）龐大的隊裡成員能超過５０只。覓食時會在街上或森林裡吵吵鬧鬧地四處盤旋。（藍羽毛）性情和戰鬥方式都很粗暴。會衝進對手的懷裡，用自己的肉身發動攻擊。（黃羽毛）不擅長單獨行動。凝聚力很強，靠著與夥伴互相合作而生存了下來。（白羽毛）", 6, 1], ["岩鹽寶可夢", "出生在地底的岩鹽層。原意分享貴重的鹽巴，因此在過去非常受到重視。", 4, 1], ["岩鹽寶可夢", "朝著獵物噴出鹽，並將其做成鹽醃物。獵物體內的水分會在此過程中被奪走。", 6, 1], ["岩鹽寶可夢", "只要它摩擦指尖，搓出鹽來撒在受傷的寶可夢身上，無論再重的傷都能瞬間癒合。", 23, 1], ["小火星寶可夢", "生命寄宿在燃燒的木炭上，變成了寶可夢。即使面對強敵，也會以燃燒的鬥志來迎戰。", 6, 1], ["火戰士寶可夢", "藉助立下諸多功勳的戰士所穿的鎧甲進化而來的樣子。是忠心耿耿的寶可夢。", 15, 1], ["火劍士寶可夢", "雙臂的火焰之劍是靠著得志前就亡命的劍士的怨念而燃燒。", 16, 1], ["電蝌蚪寶可夢", "通過搖晃尾巴來發電。若感知到有危險，會閃爍頭部來通知夥伴。", 3, 1], ["電蛙寶可夢", "只要伸縮胖嘟嘟的身體，就能讓肚子上的發電臍產生大量的電氣。", 12, 1], ["海燕寶可夢", "當翅膀的骨頭受到風吹時，就能製造電力。會衝進海里讓獵物觸電後將其捕獲。", 4, 1], ["軍艦鳥寶可夢", "通過膨脹喉囊來增強電力。乘著風可以在１天內就飛上７００公里。", 14, 1], ["小輩寶可夢", "為了不被對手看扁而總是皺著一張臉，卻反而會讓哭泣的孩子破涕為笑。", 5, 1], ["大佬寶可夢", "大大的喉囊裡可以儲存能量。會一口氣釋放能量將敵人轟飛。", 11, 1], ["毒鼠寶可夢", "雖然性格溫和，但一旦被誰激怒，就會用滲入了毒的鋒利門牙咬住對方，使其全身麻痺。", 2, 1], ["毒猴寶可夢", "它會把隨著自己所吃食物而變色的毒唾液塗在指頭上，然後在森林的樹木上畫圖案。", 7, 1], ["滾草寶可夢", "無法昇天的靈魂在風的吹拂下被捲進枯草裡，變成了寶可夢。", 6, 1], ["滾草寶可夢", "張開頭部的枝條來吞食獵物。在盡情吸食精氣之後，就會把獵物吐出來扔掉。", 12, 1], ["木耳寶可夢", "棲息在潮溼的森林裡。它身上脫落的薄片富有嚼勁，非常美味。", 9, 1], ["木耳寶可夢", "會在森林深處建造集體生活用的聚落。非常厭惡有外來者靠近。", 19, 1], ["埋伏寶可夢", "會倒掛在懸崖上等待獵物。但那會讓它的血液倒流，因此等不了太長的時間。", 13, 1], ["熱辣寶可夢", "沐浴在太陽下越久，體內的辣味成分就會變得越多，招式也會變得越來越辣。", 3, 1], ["熱辣寶可夢", "把辣味成分轉換成火之能量，然後從紅色的頭朝四周發射出辣到爆炸的火焰。", 9, 1], ["滾動寶可夢", "將超能力混進泥土和沙子裡製作泥球。泥球比自己的命還重要。", 2, 1], ["滾動寶可夢", "支撐著球的身體幾乎不動，因此人們認為它的本體其實是在球裡面。", 3, 1], ["褶邊寶可夢", "由腹部的褶邊放射出的精神力量能讓它浮在腳尖距離地面僅有１釐米的空中。", 2, 1], ["鴕鳥寶可夢", "大大的眼睛會放出精神力量使對手無法動彈。與外表不同，性格很兇暴。", 19, 1], ["錘鍊寶可夢", "揮動手工製造的錘子來保護自己，但卻經常被會吃金屬的寶可夢搶走錘子。", 4, 1], ["錘子寶可夢", "為了製造又大又堅固的錘子，會去襲擊劈斬司令的群體然後收集金屬。", 7, 1], ["錘子寶可夢", "智力高超，性格豪邁。會用錘子打飛岩石來攻擊飛在空中的鋼鎧鴉。", 7, 1], ["糯鰻寶可夢", "就算身處２０米之外，它也能嗅出輕身鱈散發出的氣味，然後躲進沙子裡藏身。", 12, 1], ["糯鰻寶可夢", "不同於外表，它性格很粗暴。會用長長的身體勒住獵物，然後將其拖進自己的巢穴裡。", 12, 1], ["掉東西寶可夢", "用胸部的絨毛和脫落的羽毛做成袋子，然後把東西放進去，並從高處往下丟著玩耍。", 15, 1], ["海豚寶可夢", "喜歡用尾鰭的水環和夥伴一起玩耍。會通過超音波來感知生物的心情。", 13, 1], ["海豚寶可夢", "只要聽見夥伴求助的聲音，它就會改變自己的樣子。那瞬間絕不會讓誰看見。（平凡形態）太古基因覺醒之後的樣子。力氣之大，用單邊的鰭就能輕鬆舉起遊輪。（全能形態）", 13, 1], ["單汽缸寶可夢", "據說是神秘的毒寶可夢鑽進了放置於廢棄工廠的引擎裡，從而誕生了它。", 10, 1], ["多汽缸寶可夢", "在增加到８個之多的汽缸裡引爆混有毒素和岩石成分的氣體來製造能量。", 18, 1], ["坐騎寶可夢", "似乎自古以來就會讓人類坐在背上。１萬年前的壁畫裡描繪著那樣的情景。", 16, 1], ["蚯蚓寶可夢", "遭到敵人攻擊時，會把體毛當做拳頭使用，朝著敵人大秀拳頭風暴。", 25, 1], ["礦石寶可夢", "從洞窟的壁上吸取營養。包覆在身上的花瓣是用毒所凝聚的結晶做成的。", 7, 1], ["礦石寶可夢", "只要感應到危險，就會張開結晶的花瓣，從圓錐形的身體發射光束。", 15, 1], ["鬼犬寶可夢", "據說它是由還未接觸人類就去世的流浪犬寶可夢轉生而來的。", 6, 1], ["鬼犬寶可夢", "平時都在墓地裡睡覺。在為數眾多的犬寶可夢中，它是對主人最為忠誠的。", 20, 1], ["同步寶可夢", "為了避免積蓄在肚子裡的能量流出，它似乎會把自己的脖子系在頸根部上。", 16, 1], ["陸鯨寶可夢", "自遠古時代由大海上岸後，就開始在陸地上生活。似乎與吼吼鯨是相近的物種。", 12, 1], ["陸鯨寶可夢", "會在冰雪地帶回遊。以強韌的肌肉和厚實的皮下脂肪來保護身體。", 45, 1], ["卸除寶可夢", "捨棄不必要的肉，能讓心靈得以磨礪，精神力量得以提升。贅肉口味清淡，卻十分美味。", 25, 1], ["大鯰寶可夢", "雖然是個大胃王，卻不怎麼擅長捕食。會和米立龍聯手捕捉獵物。", 120, 1], ["擬態寶可夢", "小型的龍寶可夢。會住在吃吼霸嘴裡，保護自己免於外敵襲擊。（上弓姿勢）身體的顏色和花紋會有差異，似乎是為了便於引誘獵物，而配合其喜好產生的變化。（下垂姿勢）鳥寶可夢是它主要的獵物。對自己的弱小心知肚明，因此會和夥伴結伴狩獵。（平挺姿勢）", 3, 1], ["憤怒猴寶可夢", "當怒氣突破臨界點時，它獲得了能夠擺脫肉體束縛的力量。", 12, 1], ["刺魚寶可夢", "一旦遭到敵人襲擊，就會從軀體伸出粗粗的刺來反擊。此招式很危險，需有切斷身體的覺悟。", 18, 1], ["長頸寶可夢", "通過同步頭部和尾巴的腦波，來讓自己的超能力提升到了麒麟奇的１０倍之高。", 32, 1], ["地蛇寶可夢", "會用堅硬的尾巴來挖穿地下深處的巖盤來築巢。巢穴長達１０公里。（二節形態）性情溫馴，會讓誤闖進巢穴的寶可夢騎到自己的背上，並將其送到入口。（三節形態）", 36, 1], ["大刀寶可夢", "在氣勢磅礴的軍團中，只有站上頂點的那隻劈斬司令才能進化成僕刀將軍。", 20, 1], ["悖謬寶可夢", "近年有人目擊到它。雄偉牙這個名字來自於某本書裡記載的生物。", 22, 1], ["悖謬寶可夢", "過去只有１次目擊紀錄。這隻寶可夢與古老的探險記所記載的神秘生物長得很像。", 12, 1], ["悖謬寶可夢", "某本書中記載的一種叫做猛惡菇的生物有可能就是這隻寶可夢。", 12, 1], ["悖謬寶可夢", "這隻寶可夢與某本書中出現的一種叫振翼發的生物有著相似的特徵。", 14, 1], ["悖謬寶可夢", "這隻神秘的寶可夢與古老的書中介紹的名為爬地翅的生物有相似點。", 32, 1], ["悖謬寶可夢", "沒有捕獲記錄。資料不足。其特徵與某本探險記中所記載的生物一致。", 23, 1], ["悖謬寶可夢", "它與超自然雜誌中所介紹的外星人送來的科學兵器十分相似。", 9, 1], ["悖謬寶可夢", "它的外形就像是超自然雜誌所報道的誕生於太古文明的機器人。", 6, 1], ["悖謬寶可夢", "與超自然雜誌曾獨家報道過的某運動員被改造成機械生化人的樣子很相似。", 18, 1], ["悖謬寶可夢", "它與超自然雜誌曾報道過的寶可夢很相似。報道中的寶可夢是愛上機器人的三首惡龍所生的孩子。", 13, 1], ["悖謬寶可夢", "與超自然雜誌中所介紹的監視人類的ＵＦＯ這種未知物體很相似。", 12, 1], ["悖謬寶可夢", "它與可疑雜誌所報道的１０億年後的班基拉斯有部分特徵相似。", 16, 1], ["冰鰭寶可夢", "會用背鰭來吸收熱量，並將其轉換成冰之能量。溫度越高，積累的能量就越多。", 5, 1], ["冰鰭寶可夢", "會凍結周圍的空氣，以冰之面罩來保護臉部，並將背鰭變為冰劍。", 8, 1], ["冰龍寶可夢", "從嘴裡噴射極低溫的冷氣。即使是灼熱的熔岩，也能使其在一瞬間變成冰塊。", 21, 1], ["寶箱寶可夢", "大約１５００年前在寶箱裡出生。若有壞蛋打算偷走寶藏，就會被它吸走精氣。（寶箱形態）從滲入硬幣裡的熱情中誕生。似乎會為了回到原本的寶箱裡而在四處徘徊。（徒步形態）", 3, 1], ["寶者寶可夢", "據說它的身體是由１０００枚硬幣組成的。喜歡與人親近，不管與誰都能立刻處好關係。", 12, 1], ["災厄寶可夢", "有人曾把王的惡行記於木簡而因此遭到了處罰，其恨意裹上了枯葉，變成了寶可夢。", 15, 1], ["災厄寶可夢", "會操控１００噸的積雪。在自己引起的雪崩中自由進出，天真無邪地玩耍。", 19, 1], ["災厄寶可夢", "注入在古老儀式中使用的器皿裡的恐懼之心周圍凝聚起土石，變成了寶可夢。", 27, 1], ["災厄寶可夢", "會操控３０００度的火焰。熔化岩石和沙礫來做成熔岩海，並在裡邊悠閒自在地游泳。", 4, 1], ["悖謬寶可夢", "它有可能就是謎團重重的探險記中被記載為轟鳴月這個名字的生物。", 20, 1], ["悖謬寶可夢", "它與超自然雜誌所報道的瘋狂科學家的發明有幾項相近的特徵。", 14, 1], ["悖謬寶可夢", "它似乎就是古老的探險記所提到的翼大王本尊。據記載，它曾用拳頭擊裂大地。（完全形態）生態等詳情全都不明。故勒頓這個名字是由發現它的博士命名而來。（制限形態）", 25, 1], ["悖謬寶可夢", "關於它的詳情尚且不明。與摩托蜥有著相似的印象，但強大與冷酷的程度遠超摩托蜥。（完整模式）古老的探險記中記載的一種叫做鐵大蛇的神秘物體與它的特徵一致。（受限模式）", 35, 1], ["悖謬寶可夢", "充滿謎團的殘暴生物。名字來源於古老探險記中所記載的水之怪物。", 35, 1], ["悖謬寶可夢", "與超自然雜誌中介紹過的未來的畢力吉翁的樣子有多個特徵相吻合。", 15, 1], ["糖蘋果寶可夢", "以僅能在某地區栽培的特殊蘋果進化而成。是２只為一體的寶可夢。", 4, 1], ["抹茶寶可夢", "據說是死前未能在茶道上登峰造極的茶道家的遺恨附到抹茶上所變成的寶可夢。（冒牌貨的樣子）會將由粉末構成的身體中的一部分灑到食物上，然後吸取舔了粉末的對手的精氣。（高檔貨的樣子）", 1, 1], ["抹茶寶可夢", "雖然會假裝成茶企圖吸取誤飲者的精氣，但經常會被識破。（凡作的樣子）會住到由著名燒製技藝大師所製作的精美茶碗中。是讓愛好者痴迷不已的寶可夢。（傑作的樣子）", 2, 1], ["隨從寶可夢", "脖子上的毒素鎖鏈刺激了全身的肌肉，讓身體變得更為強壯。", 18, 1], ["隨從寶可夢", "由能激發潛能的毒素構成的鎖鏈刺激了腦部，開發出了精神力量。", 10, 1], ["隨從寶可夢", "受到卷在身上的鎖鏈所釋放的毒素刺激，獲得了美妙的身姿和聲音。", 14, 1], ["面具寶可夢", "屬性根據身著的面具而改變。會以敏捷的身手和踢技將敵人玩弄於股掌之中。（碧草面具）這是它攻守兼備的樣子，會像不斷湧出的水一樣無間斷地使出招式。（水井面具）這是它最具攻擊性的樣子，能夠如爐中熊熊燃燒的火焰般猛烈攻擊敵人。（火灶面具）這是它防守優秀的樣子，能夠如支撐住家的地基般承受沉重的衝擊。（礎石面具）", 12, 1], ["合金寶可夢", "從周圍收集靜電。以四肢著地的姿勢射出的光束威力極強。", 20, 1], ["蘋果大蛇寶可夢", "７只蛇蟲蟲生活在由蜜糖製成的蘋果中。由正中間的蛇蟲蟲負責發號施令。", 18, 1], ["悖謬寶可夢", "目擊報告十分少。有把它噴出火柱大鬧的樣子拍攝下來的短片存在。", 35, 1], ["悖謬寶可夢", "據說會從體毛釋放出雷電將周圍燒燬。具體詳情不明。", 52, 1], ["悖謬寶可夢", "與可疑雜誌中提到的由邪惡組織改造代拉基翁而成的寶可夢長得很相似。", 15, 1], ["悖謬寶可夢", "與超自然雜誌中介紹的名為勾帕路翁型最新兵器的神秘物體長得很相似。", 16, 1], ["太晶寶可夢", "通過將能量變為堅硬的結晶來保護自身。堪稱太晶之源的寶可夢。（普通形態）一旦察覺到危險，它就會用太晶的結晶製作出堅固的甲殼以備戰。（太晶形態）太晶能量異常增強後的樣子。與古代人所認為的世界很像。（星晶形態）", 2, 1], ["支配寶可夢", "會讓對手吃下能提升慾望和能力的毒粘糕，然後通過鎖鏈控制對手。", 3, 1]];
